-- 0025 — Étapes des recettes encore plus détaillées : une action par étape (environ 9 par
-- recette au lieu de 5), mise en place séparée, feu, temps, repère visuel et la raison des
-- gestes importants. Contenu uniquement : mêmes recettes, mêmes ingrédients, aucune quantité
-- dans le texte (les portions s'ajustent). Le matériel est recalculé par le déclencheur.
-- La table temporaire ci-dessous n'a pas besoin de RLS : elle est supprimée à la fin.

create temporary table _new_steps (slug text not null, position smallint not null, instruction text not null);


do $$
declare
  v_missing text;
begin
  select string_agg(distinct n.slug, ', ') into v_missing
  from _new_steps n where not exists (select 1 from public.recipes r where r.slug = n.slug);
  if v_missing is not null then
    raise exception 'Recettes introuvables : %', v_missing;
  end if;
end;
$$;

delete from public.recipe_steps s
using public.recipes r
where s.recipe_id = r.id and r.slug in (select distinct slug from _new_steps);

select r.id, n.position, n.instruction
from _new_steps n join public.recipes r on r.slug = n.slug;

drop table _new_steps;
