insert into _new_steps (slug, position, instruction) values
  ('agneau-raisins-semoule', 1, 'Sortir l''agneau du réfrigérateur 15 minutes avant de commencer et l''éponger : une viande sèche et à température dore mieux.'),
  ('agneau-raisins-semoule', 2, 'Éplucher les oignons et les émincer finement. Éplucher les carottes et les couper en rondelles épaisses d''environ 1 cm, pour qu''elles restent entières après la longue cuisson.'),
  ('agneau-raisins-semoule', 3, 'Chauffer l''huile dans une cocotte à feu vif jusqu''à ce qu''elle frémisse.'),
  ('agneau-raisins-semoule', 4, 'Dorer l''agneau en deux fournées, 3 à 4 minutes chacune, sans le remuer sans arrêt : les morceaux doivent être bien colorés sur toutes les faces. Réserver sur une assiette.'),
  ('agneau-raisins-semoule', 5, 'Baisser à feu moyen, ajouter les oignons et les faire revenir 5 minutes en grattant le fond, jusqu''à ce qu''ils soient translucides.'),
  ('agneau-raisins-semoule', 6, 'Ajouter la cannelle et le cumin et remuer 1 minute, juste le temps qu''ils embaument, sans les laisser brûler.'),
  ('agneau-raisins-semoule', 7, 'Remettre l''agneau et son jus, ajouter les carottes, l''eau et le cube émietté. Porter à ébullition.'),
  ('agneau-raisins-semoule', 8, 'Couvrir et laisser mijoter 1 h 15 à feu doux, en remuant toutes les 20 minutes. La viande est prête quand elle se défait à la fourchette.'),
  ('agneau-raisins-semoule', 9, 'Ajouter les raisins secs et le miel, mélanger et poursuivre 15 minutes à découvert, pour que la sauce réduise et devienne légèrement sirupeuse.'),
  ('agneau-raisins-semoule', 10, 'Pendant ce temps, faire griller les amandes 3 à 4 minutes à sec dans une poêle à feu moyen, en remuant, jusqu''à ce qu''elles blondissent et sentent le grillé.'),
  ('agneau-raisins-semoule', 11, 'Préparer la semoule : la verser dans un saladier, la couvrir du même volume d''eau bouillante, couvrir et laisser gonfler 5 minutes, puis l''égrener à la fourchette.'),
  ('agneau-raisins-semoule', 12, 'Servir l''agneau et sa sauce sur la semoule, parsemé d''amandes grillées.'),
  ('aubergines-parmesane', 1, 'Préchauffer le four à 200 °C.'),
  ('aubergines-parmesane', 2, 'Laver les aubergines, retirer le pédoncule et les couper en tranches d''environ 1 cm dans la longueur.'),
  ('aubergines-parmesane', 3, 'Poser les tranches sur la plaque du four en une seule couche et les badigeonner d''huile sur les deux faces : l''aubergine absorbe vite l''huile, répartir uniformément.'),
  ('aubergines-parmesane', 4, 'Rôtir 20 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient tendres et dorées. Saler légèrement.'),
  ('aubergines-parmesane', 5, 'Pendant ce temps, peler et écraser l''ail. Le mettre dans une casserole avec le coulis et laisser mijoter 10 minutes à feu doux, à demi couvert.'),
  ('aubergines-parmesane', 6, 'Égoutter la mozzarella et la couper en tranches fines. Effeuiller le basilic.'),
  ('aubergines-parmesane', 7, 'Baisser le four à 190 °C. Étaler une fine couche de sauce au fond d''un plat allant au four.'),
  ('aubergines-parmesane', 8, 'Couvrir d''une couche d''aubergines, puis de sauce, de mozzarella et de quelques feuilles de basilic. Recommencer jusqu''à épuisement, en terminant par de la sauce.'),
  ('aubergines-parmesane', 9, 'Parsemer de parmesan râpé sur toute la surface.'),
  ('aubergines-parmesane', 10, 'Enfourner 20 minutes, jusqu''à ce que le dessus gratine et que la sauce bouillonne sur les bords.'),
  ('aubergines-parmesane', 11, 'Laisser reposer 5 minutes hors du four avant de servir : les couches se tiennent mieux.'),
  ('blanquette-veau', 1, 'Mettre le veau dans un faitout et le couvrir largement d''eau froide.'),
  ('blanquette-veau', 2, 'Porter à ébullition à feu vif. Pendant 2 à 3 minutes, retirer à l''écumoire la mousse grise qui remonte à la surface : c''est ce qui donne un bouillon clair.'),
  ('blanquette-veau', 3, 'Éplucher l''oignon et le couper en deux. Éplucher les carottes et les couper en tronçons de 4 cm.'),
  ('blanquette-veau', 4, 'Ajouter dans le faitout les cubes émiettés, l''oignon, les carottes et le laurier.'),
  ('blanquette-veau', 5, 'Couvrir et laisser cuire 1 h 30 à petit frémissement, sans bouillir : la viande doit être fondante quand on la pique.'),
  ('blanquette-veau', 6, 'Environ 20 minutes avant la fin, cuire le riz dans une casserole d''eau bouillante 12 minutes, puis l''égoutter.'),
  ('blanquette-veau', 7, 'Couper le bout terreux des champignons et les couper en quartiers. Les faire revenir 5 minutes dans une noix de beurre, dans une poêle à feu moyen, jusqu''à ce qu''ils soient dorés.'),
  ('blanquette-veau', 8, 'Égoutter la viande et les carottes avec une écumoire et garder le bouillon. Retirer l''oignon et le laurier.'),
  ('blanquette-veau', 9, 'Dans une casserole, faire fondre le reste du beurre à feu moyen. Ajouter la farine et remuer 2 minutes au fouet, sans laisser colorer : c''est le roux.'),
  ('blanquette-veau', 10, 'Verser 60 cl de bouillon chaud petit à petit en fouettant sans arrêt, pour éviter les grumeaux.'),
  ('blanquette-veau', 11, 'Laisser épaissir 5 minutes à feu doux, jusqu''à ce que la sauce nappe le dos d''une cuillère.'),
  ('blanquette-veau', 12, 'Hors du feu, ajouter la crème et le jus du citron. Goûter, saler et poivrer.'),
  ('blanquette-veau', 13, 'Remettre la viande, les carottes et les champignons dans la sauce et réchauffer 10 minutes à feu très doux, sans faire bouillir pour que la sauce ne tourne pas.'),
  ('blanquette-veau', 14, 'Servir bien chaud avec le riz.'),
  ('boeuf-bourguignon', 1, 'Éplucher et émincer les oignons. Peler les gousses d''ail et les écraser. Éplucher les carottes et les couper en rondelles épaisses.'),
  ('boeuf-bourguignon', 2, 'Bien éponger la viande avec du papier absorbant : une viande humide bout au lieu de dorer.'),
  ('boeuf-bourguignon', 3, 'Chauffer l''huile dans une cocotte à feu vif.'),
  ('boeuf-bourguignon', 4, 'Dorer la viande en trois fournées, 4 minutes chacune, sans la remuer pendant la première minute. Elle doit être bien brune sur toutes les faces. Réserver sur une assiette.'),
  ('boeuf-bourguignon', 5, 'Baisser à feu moyen. Faire revenir les lardons et les oignons 5 minutes dans la graisse restante, en grattant les sucs au fond de la cocotte.'),
  ('boeuf-bourguignon', 6, 'Saupoudrer de farine et remuer 1 minute pour qu''elle cuise légèrement : elle épaissira la sauce.'),
  ('boeuf-bourguignon', 7, 'Remettre la viande et son jus, puis verser le vin rouge en grattant le fond.'),
  ('boeuf-bourguignon', 8, 'Ajouter l''ail, les carottes, le thym et le laurier. Compléter d''eau juste à hauteur de la viande si besoin. Saler et poivrer.'),
  ('boeuf-bourguignon', 9, 'Porter à ébullition, puis couvrir et laisser mijoter 2 h 30 à feu très doux : la sauce doit à peine frémir. Remuer toutes les 30 minutes.'),
  ('boeuf-bourguignon', 10, 'Pendant la dernière demi-heure, couper les champignons en quartiers et les faire dorer 5 minutes dans une poêle chaude, sans matière grasse.'),
  ('boeuf-bourguignon', 11, 'Ajouter les champignons à la cocotte et cuire encore 30 minutes. La viande est prête quand elle se coupe à la cuillère.'),
  ('boeuf-bourguignon', 12, 'Retirer le laurier et le thym, goûter et rectifier l''assaisonnement avant de servir.'),
  ('boeuf-brocoli-saute', 1, 'Dans un bol, mélanger les lanières de bœuf avec la fécule et la moitié de la sauce soja. Laisser reposer pendant la suite : la fécule rendra la viande tendre et la sauce nappante.'),
  ('boeuf-brocoli-saute', 2, 'Lancer le riz dans une casserole d''eau bouillante, 10 à 12 minutes, puis l''égoutter et le garder au chaud à couvert.'),
  ('boeuf-brocoli-saute', 3, 'Détailler le brocoli en petits bouquets de taille égale.'),
  ('boeuf-brocoli-saute', 4, 'Plonger les bouquets 2 minutes dans une casserole d''eau bouillante, puis les égoutter : ils doivent rester vert vif et croquants.'),
  ('boeuf-brocoli-saute', 5, 'Peler et hacher l''ail. Peler le gingembre à la cuillère et le râper.'),
  ('boeuf-brocoli-saute', 6, 'Chauffer l''huile de tournesol dans une poêle ou un wok à feu très vif, jusqu''à ce qu''elle fume légèrement.'),
  ('boeuf-brocoli-saute', 7, 'Ajouter le bœuf en une seule couche et le laisser saisir 1 minute sans toucher, puis le faire sauter 1 minute de plus : il doit être doré mais encore tendre.'),
  ('boeuf-brocoli-saute', 8, 'Ajouter l''ail et le gingembre et remuer 30 secondes.'),
  ('boeuf-brocoli-saute', 9, 'Ajouter le brocoli et faire sauter 2 minutes.'),
  ('boeuf-brocoli-saute', 10, 'Verser le reste de sauce soja et l''huile de sésame, mélanger 30 secondes pour enrober.'),
  ('boeuf-brocoli-saute', 11, 'Servir aussitôt sur le riz.'),
  ('bolognaise', 1, 'Éplucher l''oignon et l''ail et les hacher finement. Éplucher la carotte et la couper en tout petits dés : ils fondront dans la sauce.'),
  ('bolognaise', 2, 'Chauffer l''huile dans une grande casserole à feu moyen.'),
  ('bolognaise', 3, 'Faire revenir l''oignon, la carotte et l''ail 5 minutes en remuant, jusqu''à ce que l''oignon soit translucide.'),
  ('bolognaise', 4, 'Monter à feu vif et ajouter la viande. La faire dorer 5 minutes en l''émiettant à la cuillère en bois, jusqu''à ce qu''elle ne soit plus rosée.'),
  ('bolognaise', 5, 'Ajouter le concentré de tomate et remuer 1 minute pour le faire légèrement caraméliser.'),
  ('bolognaise', 6, 'Verser les tomates concassées et ajouter les herbes. Bien mélanger.'),
  ('bolognaise', 7, 'Porter à frémissement, puis laisser mijoter 30 minutes à feu doux, à demi couvert, en remuant toutes les 10 minutes. La sauce doit épaissir et l''huile remonter légèrement en surface.'),
  ('bolognaise', 8, 'Dix minutes avant la fin, porter une grande casserole d''eau à ébullition et cuire les pâtes 8 à 10 minutes (voir le paquet).'),
  ('bolognaise', 9, 'Goûter la sauce et rectifier l''assaisonnement.'),
  ('bolognaise', 10, 'Égoutter les pâtes et les servir nappées de sauce, avec le parmesan râpé.'),
  ('boulettes-boeuf-sauce-tomate', 1, 'Éplucher et hacher finement l''oignon et l''ail. Ciseler le persil.'),
  ('boulettes-boeuf-sauce-tomate', 2, 'Dans un saladier, mélanger le bœuf, l''œuf, la chapelure, la moitié de l''oignon, l''ail et le persil. Saler et poivrer.'),
  ('boulettes-boeuf-sauce-tomate', 3, 'Malaxer à la main juste assez pour que le mélange se tienne : trop travaillé, il donne des boulettes dures.'),
  ('boulettes-boeuf-sauce-tomate', 4, 'Se mouiller les mains et former des boulettes de la taille d''une noix. Les poser sur une assiette.'),
  ('boulettes-boeuf-sauce-tomate', 5, 'Chauffer l''huile dans une sauteuse à feu moyen-vif.'),
  ('boulettes-boeuf-sauce-tomate', 6, 'Dorer les boulettes 5 minutes en les faisant rouler délicatement, jusqu''à ce qu''elles soient colorées de tous côtés.'),
  ('boulettes-boeuf-sauce-tomate', 7, 'Ajouter le reste d''oignon et le faire revenir 2 minutes entre les boulettes.'),
  ('boulettes-boeuf-sauce-tomate', 8, 'Verser le coulis, couvrir et laisser mijoter 20 minutes à feu doux : les boulettes doivent être cuites à cœur.'),
  ('boulettes-boeuf-sauce-tomate', 9, 'Pendant ce temps, cuire les spaghetti dans une grande casserole d''eau bouillante 9 à 11 minutes (voir le paquet), puis les égoutter.'),
  ('boulettes-boeuf-sauce-tomate', 10, 'Servir les spaghetti nappés de sauce et de boulettes, avec le parmesan râpé.'),
  ('bowl-saumon-fume-avocat', 1, 'Rincer le riz dans une passoire jusqu''à ce que l''eau soit claire.'),
  ('bowl-saumon-fume-avocat', 2, 'Le cuire dans une casserole d''eau bouillante 11 à 12 minutes, l''égoutter et le laisser tiédir 10 minutes dans un saladier.'),
  ('bowl-saumon-fume-avocat', 3, 'Laver le concombre et le couper en petits dés.'),
  ('bowl-saumon-fume-avocat', 4, 'Éplucher la mangue, retirer la chair autour du noyau et la couper en dés.'),
  ('bowl-saumon-fume-avocat', 5, 'Couper l''avocat en deux, retirer le noyau, prélever la chair à la cuillère et la couper en dés. Le préparer en dernier pour qu''il ne noircisse pas.'),
  ('bowl-saumon-fume-avocat', 6, 'Détailler le saumon fumé en lanières.'),
  ('bowl-saumon-fume-avocat', 7, 'Dans un petit bol, mélanger la sauce soja avec le jus du citron vert.'),
  ('bowl-saumon-fume-avocat', 8, 'Répartir le riz dans deux bols, puis disposer le saumon, l''avocat, le concombre et la mangue en petits tas côte à côte.'),
  ('bowl-saumon-fume-avocat', 9, 'Arroser de sauce, parsemer de sésame et servir aussitôt.'),
  ('buddha-bowl-quinoa', 1, 'Préchauffer le four à 200 °C.'),
  ('buddha-bowl-quinoa', 2, 'Éplucher la patate douce et la couper en cubes d''environ 2 cm, de taille égale pour une cuisson uniforme.'),
  ('buddha-bowl-quinoa', 3, 'Égoutter et rincer les pois chiches, puis bien les sécher dans un torchon : ils deviendront plus croustillants.'),
  ('buddha-bowl-quinoa', 4, 'Sur la plaque du four, mélanger la patate douce et les pois chiches avec l''huile et le paprika, en une seule couche sans qu''ils se chevauchent.'),
  ('buddha-bowl-quinoa', 5, 'Rôtir 30 minutes en remuant à mi-cuisson, jusqu''à ce que la patate douce soit tendre et dorée sur les bords.'),
  ('buddha-bowl-quinoa', 6, 'Pendant ce temps, rincer le quinoa dans une passoire fine pour retirer son amertume.'),
  ('buddha-bowl-quinoa', 7, 'Le mettre dans une casserole avec deux fois son volume d''eau, porter à ébullition, puis couvrir et cuire 12 minutes à feu doux, jusqu''à absorption.'),
  ('buddha-bowl-quinoa', 8, 'Hors du feu, laisser gonfler 5 minutes à couvert puis l''aérer à la fourchette.'),
  ('buddha-bowl-quinoa', 9, 'Couper les avocats en deux, retirer le noyau et les couper en tranches. Laver les épinards.'),
  ('buddha-bowl-quinoa', 10, 'Répartir le quinoa dans les bols, puis disposer les légumes rôtis, les épinards et l''avocat.'),
  ('buddha-bowl-quinoa', 11, 'Arroser de jus de citron et parsemer de sésame.'),
  ('cabillaud-pane-haricots-verts', 1, 'Équeuter les haricots verts en retirant les deux extrémités.'),
  ('cabillaud-pane-haricots-verts', 2, 'Les plonger dans une casserole d''eau bouillante salée et les cuire 8 minutes : ils doivent rester légèrement croquants. Les égoutter et les garder au chaud.'),
  ('cabillaud-pane-haricots-verts', 3, 'Éponger soigneusement le poisson avec du papier absorbant, sinon la panure ne tiendra pas.'),
  ('cabillaud-pane-haricots-verts', 4, 'Préparer trois assiettes creuses : la farine, l''œuf battu avec une pincée de sel, la chapelure.'),
  ('cabillaud-pane-haricots-verts', 5, 'Passer chaque dos dans la farine en tapotant pour retirer l''excédent.'),
  ('cabillaud-pane-haricots-verts', 6, 'Le tremper ensuite dans l''œuf, puis dans la chapelure en appuyant bien sur toutes les faces.'),
  ('cabillaud-pane-haricots-verts', 7, 'Chauffer l''huile dans une poêle à feu moyen : elle doit grésiller au contact d''une miette de chapelure.'),
  ('cabillaud-pane-haricots-verts', 8, 'Cuire le poisson 4 minutes sans le bouger, le retourner délicatement à la spatule et cuire encore 4 minutes. La panure doit être dorée et la chair s''effeuiller au centre.'),
  ('cabillaud-pane-haricots-verts', 9, 'Égoutter rapidement sur du papier absorbant.'),
  ('cabillaud-pane-haricots-verts', 10, 'Servir avec les haricots verts et des quartiers de citron.'),
  ('cabillaud-poireaux', 1, 'Couper la base et le haut vert foncé des poireaux, les fendre en deux et les rincer sous l''eau pour retirer la terre. Les émincer finement.'),
  ('cabillaud-poireaux', 2, 'Si vous servez des pommes de terre, les éplucher, les couper en deux et les cuire 20 minutes à la vapeur.'),
  ('cabillaud-poireaux', 3, 'Faire fondre le beurre dans une sauteuse à feu doux.'),
  ('cabillaud-poireaux', 4, 'Ajouter les poireaux, couvrir et les laisser fondre 15 minutes en remuant de temps en temps : ils doivent devenir tendres sans colorer.'),
  ('cabillaud-poireaux', 5, 'Ajouter la crème, saler et poivrer, puis laisser réduire 5 minutes à découvert, jusqu''à ce que la sauce nappe.'),
  ('cabillaud-poireaux', 6, 'Éponger les dos de cabillaud et les saler légèrement.'),
  ('cabillaud-poireaux', 7, 'Les poser sur la fondue de poireaux, couvrir et cuire 8 minutes à feu doux : la chair doit devenir blanche et nacrée.'),
  ('cabillaud-poireaux', 8, 'Arroser de jus de citron au moment de servir.'),
  ('cabillaud-poireaux', 9, 'Servir avec les pommes de terre vapeur.'),
  ('cake-banane', 1, 'Préchauffer le four à 180 °C.'),
  ('cake-banane', 2, 'Beurrer un moule à cake avec une noisette du beurre. Faire fondre le reste du beurre et le laisser tiédir.'),
  ('cake-banane', 3, 'Éplucher les bananes et les écraser à la fourchette dans un saladier, jusqu''à obtenir une purée avec quelques petits morceaux.'),
  ('cake-banane', 4, 'Ajouter les œufs et le sucre et fouetter 1 minute.'),
  ('cake-banane', 5, 'Verser le beurre fondu tiède et mélanger.'),
  ('cake-banane', 6, 'Ajouter la farine et la levure et mélanger juste assez pour qu''il ne reste plus de traces de farine : trop mélangée, la pâte donne un cake compact.'),
  ('cake-banane', 7, 'Concasser grossièrement les noix et les incorporer.'),
  ('cake-banane', 8, 'Verser la pâte dans le moule et lisser le dessus.'),
  ('cake-banane', 9, 'Enfourner 45 minutes. Une lame plantée au centre doit ressortir sèche ; si le dessus brunit trop vite, le couvrir d''une feuille de papier.'),
  ('cake-banane', 10, 'Laisser tiédir 10 minutes dans le moule, puis démouler sur une grille.'),
  ('chili-con-carne', 1, 'Éplucher et hacher les oignons et l''ail. Épépiner le poivron et le couper en petits dés.'),
  ('chili-con-carne', 2, 'Chauffer l''huile dans une cocotte à feu moyen.'),
  ('chili-con-carne', 3, 'Faire revenir les oignons, le poivron et l''ail 5 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('chili-con-carne', 4, 'Monter à feu vif, ajouter le bœuf et le faire colorer 5 minutes en l''émiettant à la cuillère en bois.'),
  ('chili-con-carne', 5, 'Ajouter le cumin, le paprika et le piment et remuer 1 minute pour libérer leurs arômes.'),
  ('chili-con-carne', 6, 'Rincer et égoutter les haricots.'),
  ('chili-con-carne', 7, 'Ajouter les tomates et les haricots, saler et mélanger.'),
  ('chili-con-carne', 8, 'Porter à frémissement, puis laisser mijoter 40 minutes à feu doux, à demi couvert, en remuant toutes les 10 minutes. Le chili doit être épais.'),
  ('chili-con-carne', 9, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('chili-con-carne', 10, 'Goûter le chili, rectifier l''assaisonnement et servir sur le riz.'),
  ('chili-sin-carne', 1, 'Éplucher et hacher l''oignon et l''ail. Épépiner le poivron et le couper en dés.'),
  ('chili-sin-carne', 2, 'Chauffer l''huile dans une cocotte à feu moyen.'),
  ('chili-sin-carne', 3, 'Faire revenir l''oignon, l''ail et le poivron 5 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('chili-sin-carne', 4, 'Ajouter le cumin, le paprika et le piment et remuer 1 minute.'),
  ('chili-sin-carne', 5, 'Verser les tomates et laisser mijoter 15 minutes à feu doux.'),
  ('chili-sin-carne', 6, 'Rincer et égoutter les haricots et le maïs.'),
  ('chili-sin-carne', 7, 'Les ajouter et cuire encore 15 minutes, jusqu''à ce que la sauce épaississe.'),
  ('chili-sin-carne', 8, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('chili-sin-carne', 9, 'Goûter, rectifier l''assaisonnement et servir le chili avec le riz.'),
  ('chou-fleur-roti-curry', 1, 'Préchauffer le four à 210 °C.'),
  ('chou-fleur-roti-curry', 2, 'Retirer les feuilles du chou-fleur et le détailler en fleurettes de taille égale.'),
  ('chou-fleur-roti-curry', 3, 'Égoutter, rincer et bien sécher les pois chiches.'),
  ('chou-fleur-roti-curry', 4, 'Sur la plaque du four, mélanger le chou-fleur et les pois chiches avec l''huile, le curry et le sel. Les étaler en une seule couche.'),
  ('chou-fleur-roti-curry', 5, 'Rôtir 35 minutes en remuant à mi-cuisson, jusqu''à ce que le chou-fleur soit tendre et bien doré sur les bords.'),
  ('chou-fleur-roti-curry', 6, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('chou-fleur-roti-curry', 7, 'Mélanger le yaourt avec le jus du citron et une pincée de sel.'),
  ('chou-fleur-roti-curry', 8, 'Ciseler la coriandre.'),
  ('chou-fleur-roti-curry', 9, 'Servir le chou-fleur et les pois chiches sur le riz, avec la sauce au yaourt et la coriandre.'),
  ('coquillettes-jambon-emmental', 1, 'Porter une grande casserole d''eau à ébullition.'),
  ('coquillettes-jambon-emmental', 2, 'Verser les coquillettes, remuer pour qu''elles ne collent pas, et les cuire 8 à 10 minutes (voir le paquet).'),
  ('coquillettes-jambon-emmental', 3, 'Pendant ce temps, couper le jambon en petits dés.'),
  ('coquillettes-jambon-emmental', 4, 'Égoutter les coquillettes et les remettre aussitôt dans la casserole, hors du feu.'),
  ('coquillettes-jambon-emmental', 5, 'Ajouter le beurre et remuer jusqu''à ce qu''il fonde.'),
  ('coquillettes-jambon-emmental', 6, 'Ajouter le jambon et l''emmental et mélanger 1 minute à feu doux, jusqu''à ce que le fromage file.'),
  ('coquillettes-jambon-emmental', 7, 'Poivrer et servir aussitôt.'),
  ('cotes-porc-pommes', 1, 'Sortir les côtes du réfrigérateur 10 minutes avant.'),
  ('cotes-porc-pommes', 2, 'Si vous servez des pommes de terre, les éplucher, les couper en deux et les cuire 20 minutes à la vapeur.'),
  ('cotes-porc-pommes', 3, 'Éplucher les pommes, retirer le cœur et les couper en quartiers. Éplucher et émincer l''oignon.'),
  ('cotes-porc-pommes', 4, 'Faire fondre la moitié du beurre dans une poêle à feu moyen-vif.'),
  ('cotes-porc-pommes', 5, 'Dorer les côtes 5 minutes par face, sans les bouger, jusqu''à ce qu''elles soient bien colorées. Saler, poivrer et les réserver sur une assiette couverte.'),
  ('cotes-porc-pommes', 6, 'Dans la même poêle, faire fondre le reste du beurre et ajouter les pommes et l''oignon.'),
  ('cotes-porc-pommes', 7, 'Les faire caraméliser 8 minutes à feu moyen en les retournant délicatement, jusqu''à ce qu''ils soient dorés et tendres.'),
  ('cotes-porc-pommes', 8, 'Ajouter la moutarde et la crème et mélanger.'),
  ('cotes-porc-pommes', 9, 'Remettre les côtes et leur jus et les réchauffer 5 minutes à feu doux en les nappant de sauce.'),
  ('cotes-porc-pommes', 10, 'Servir avec les pommes de terre vapeur.'),
  ('courgettes-farcies-boulgour', 1, 'Préchauffer le four à 190 °C.'),
  ('courgettes-farcies-boulgour', 2, 'Mettre le boulgour dans une casserole avec deux fois son volume d''eau, porter à ébullition, couvrir et cuire 10 minutes à feu doux. L''égrener à la fourchette.'),
  ('courgettes-farcies-boulgour', 3, 'Laver les courgettes et les couper en deux dans la longueur.'),
  ('courgettes-farcies-boulgour', 4, 'Les évider avec une petite cuillère en laissant un bord d''environ 5 mm. Hacher la chair retirée.'),
  ('courgettes-farcies-boulgour', 5, 'Éplucher et hacher l''oignon.'),
  ('courgettes-farcies-boulgour', 6, 'Chauffer l''huile dans une poêle à feu moyen et faire revenir l''oignon et la chair des courgettes 5 minutes.'),
  ('courgettes-farcies-boulgour', 7, 'Ajouter les tomates et cuire encore 5 minutes. Saler et poivrer.'),
  ('courgettes-farcies-boulgour', 8, 'Hors du feu, mélanger avec le boulgour, la feta émiettée et la menthe ciselée.'),
  ('courgettes-farcies-boulgour', 9, 'Ranger les courgettes dans un plat allant au four et les garnir généreusement de farce, en tassant légèrement.'),
  ('courgettes-farcies-boulgour', 10, 'Enfourner 30 minutes, jusqu''à ce que les courgettes soient tendres sous la pointe d''un couteau et le dessus doré.'),
  ('couscous-legumes', 1, 'Éplucher et émincer l''oignon.'),
  ('couscous-legumes', 2, 'Éplucher les carottes et le navet et les couper en gros tronçons. Couper les courgettes en gros morceaux : elles cuisent plus vite, on les ajoutera plus tard.'),
  ('couscous-legumes', 3, 'Chauffer l''huile dans un faitout à feu moyen.'),
  ('couscous-legumes', 4, 'Faire revenir l''oignon avec le cumin 3 minutes.'),
  ('couscous-legumes', 5, 'Ajouter les carottes, le navet, les tomates, le cube émietté et l''eau.'),
  ('couscous-legumes', 6, 'Porter à ébullition, puis couvrir et cuire 20 minutes à feu moyen-doux.'),
  ('couscous-legumes', 7, 'Rincer les pois chiches. Les ajouter avec les courgettes et cuire encore 15 minutes, jusqu''à ce que tous les légumes soient tendres.'),
  ('couscous-legumes', 8, 'Préparer la semoule : la verser dans un saladier et la couvrir du même volume d''eau bouillante.'),
  ('couscous-legumes', 9, 'Couvrir et laisser gonfler 5 minutes, puis l''égrener à la fourchette.'),
  ('couscous-legumes', 10, 'Servir la semoule avec les légumes et leur bouillon, et la harissa à part pour que chacun dose.'),
  ('crepes-jambon-fromage', 1, 'Dans un saladier, mélanger la farine et une pincée de sel.'),
  ('crepes-jambon-fromage', 2, 'Creuser un puits au centre et y casser les œufs.'),
  ('crepes-jambon-fromage', 3, 'Fouetter les œufs en incorporant la farine petit à petit depuis le centre.'),
  ('crepes-jambon-fromage', 4, 'Verser le lait progressivement en fouettant sans arrêt, pour obtenir une pâte lisse et sans grumeaux.'),
  ('crepes-jambon-fromage', 5, 'Faire fondre le beurre. En ajouter la moitié à la pâte et mélanger.'),
  ('crepes-jambon-fromage', 6, 'Laisser reposer la pâte 30 minutes si possible : les crêpes seront plus souples.'),
  ('crepes-jambon-fromage', 7, 'Chauffer une poêle à feu moyen-vif et la graisser légèrement avec un peu du reste de beurre.'),
  ('crepes-jambon-fromage', 8, 'Verser une petite louche de pâte en inclinant la poêle pour couvrir le fond. Cuire 1 minute, jusqu''à ce que les bords se décollent, retourner et cuire 30 secondes.'),
  ('crepes-jambon-fromage', 9, 'Empiler les crêpes sur une assiette au fur et à mesure.'),
  ('crepes-jambon-fromage', 10, 'Remettre une crêpe dans la poêle, la garnir d''une tranche de jambon et d''emmental, la plier en quatre et la laisser fondre 1 minute. Recommencer avec les autres.'),
  ('crepes-jambon-fromage', 11, 'Servir chaud avec la salade.'),
  ('crevettes-curry-coco', 1, 'Lancer le riz dans une casserole d''eau bouillante, 10 à 12 minutes, puis l''égoutter et le garder au chaud.'),
  ('crevettes-curry-coco', 2, 'Éplucher et émincer l''oignon. Épépiner le poivron et le couper en lanières.'),
  ('crevettes-curry-coco', 3, 'Si les crevettes sont crues avec carapace, les décortiquer en gardant la queue.'),
  ('crevettes-curry-coco', 4, 'Chauffer l''huile dans une sauteuse à feu moyen.'),
  ('crevettes-curry-coco', 5, 'Faire revenir l''oignon et le poivron 5 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('crevettes-curry-coco', 6, 'Ajouter la pâte de curry et remuer 1 minute, jusqu''à ce qu''elle embaume.'),
  ('crevettes-curry-coco', 7, 'Verser le lait de coco, bien mélanger et porter à frémissement 5 minutes.'),
  ('crevettes-curry-coco', 8, 'Ajouter les crevettes et cuire 3 à 4 minutes, jusqu''à ce qu''elles soient roses et opaques : au-delà, elles deviennent caoutchouteuses.'),
  ('crevettes-curry-coco', 9, 'Hors du feu, ajouter le jus du citron vert et la coriandre ciselée.'),
  ('crevettes-curry-coco', 10, 'Servir avec le riz.'),
  ('croque-monsieur', 1, 'Préchauffer le four à 220 °C.'),
  ('croque-monsieur', 2, 'Laisser le beurre ramollir à température ambiante, il s''étalera sans déchirer le pain.'),
  ('croque-monsieur', 3, 'Beurrer une face de chaque tranche de pain.'),
  ('croque-monsieur', 4, 'Poser la moitié des tranches sur la plaque du four, face beurrée dessous.'),
  ('croque-monsieur', 5, 'Garnir chacune d''une tranche de jambon, pliée à la taille du pain, et d''une partie de l''emmental.'),
  ('croque-monsieur', 6, 'Refermer avec les autres tranches, face beurrée dessus.'),
  ('croque-monsieur', 7, 'Parsemer le dessus du reste d''emmental.'),
  ('croque-monsieur', 8, 'Enfourner 10 minutes, jusqu''à ce que le fromage soit fondu et le pain bien doré.'),
  ('croque-monsieur', 9, 'Couper en deux en diagonale et servir chaud.'),
  ('crumble-pommes', 1, 'Préchauffer le four à 180 °C.'),
  ('crumble-pommes', 2, 'Éplucher les pommes, retirer le cœur et les couper en morceaux d''environ 2 cm.'),
  ('crumble-pommes', 3, 'Les répartir dans un plat allant au four et les saupoudrer de cannelle.'),
  ('crumble-pommes', 4, 'Dans un saladier, mélanger la farine et le sucre.'),
  ('crumble-pommes', 5, 'Ajouter le beurre bien froid coupé en dés.'),
  ('crumble-pommes', 6, 'Sabler du bout des doigts, rapidement pour que le beurre reste froid, jusqu''à obtenir de grosses miettes irrégulières.'),
  ('crumble-pommes', 7, 'Parsemer la pâte sur les pommes, sans tasser.'),
  ('crumble-pommes', 8, 'Enfourner 35 minutes, jusqu''à ce que le dessus soit bien doré et que le jus des pommes bouillonne sur les bords.'),
  ('crumble-pommes', 9, 'Laisser tiédir 10 minutes avant de servir.'),
  ('curry-pois-chiches-epinards', 1, 'Lancer le riz dans une casserole d''eau bouillante, 11 à 12 minutes, puis l''égoutter.'),
  ('curry-pois-chiches-epinards', 2, 'Éplucher et hacher l''oignon et l''ail. Peler le gingembre à la cuillère et le râper.'),
  ('curry-pois-chiches-epinards', 3, 'Égoutter et rincer les pois chiches.'),
  ('curry-pois-chiches-epinards', 4, 'Chauffer l''huile dans une sauteuse à feu moyen.'),
  ('curry-pois-chiches-epinards', 5, 'Faire revenir l''oignon, l''ail et le gingembre 5 minutes, jusqu''à ce que l''oignon soit tendre.'),
  ('curry-pois-chiches-epinards', 6, 'Ajouter le curry et remuer 1 minute pour le torréfier légèrement.'),
  ('curry-pois-chiches-epinards', 7, 'Verser les tomates et le lait de coco et bien mélanger.'),
  ('curry-pois-chiches-epinards', 8, 'Ajouter les pois chiches, porter à frémissement et laisser mijoter 15 minutes à feu doux, jusqu''à ce que la sauce épaississe.'),
  ('curry-pois-chiches-epinards', 9, 'Ajouter les épinards par poignées et remuer 1 à 2 minutes, jusqu''à ce qu''ils tombent.'),
  ('curry-pois-chiches-epinards', 10, 'Goûter, rectifier l''assaisonnement et servir avec le riz et la coriandre ciselée.'),
  ('dinde-creme-champignons', 1, 'Lancer le riz dans une casserole d''eau bouillante, 11 à 12 minutes, puis l''égoutter.'),
  ('dinde-creme-champignons', 2, 'Éplucher et émincer les échalotes. Couper le bout terreux des champignons et les émincer.'),
  ('dinde-creme-champignons', 3, 'Éponger les escalopes.'),
  ('dinde-creme-champignons', 4, 'Faire fondre la moitié du beurre dans une poêle à feu moyen-vif.'),
  ('dinde-creme-champignons', 5, 'Dorer les escalopes 3 minutes par face. Saler, poivrer et les réserver sur une assiette.'),
  ('dinde-creme-champignons', 6, 'Dans la même poêle, faire fondre le reste du beurre et faire revenir les échalotes 2 minutes.'),
  ('dinde-creme-champignons', 7, 'Ajouter les champignons et les faire revenir 5 minutes, jusqu''à ce que leur eau soit évaporée.'),
  ('dinde-creme-champignons', 8, 'Verser la crème et laisser réduire 3 minutes à feu moyen, jusqu''à ce que la sauce nappe la cuillère.'),
  ('dinde-creme-champignons', 9, 'Remettre la dinde et son jus dans la sauce 2 minutes pour la réchauffer, sans la faire bouillir.'),
  ('dinde-creme-champignons', 10, 'Parsemer de persil ciselé et servir avec le riz.'),
  ('endives-jambon', 1, 'Préchauffer le four à 200 °C.'),
  ('endives-jambon', 2, 'Retirer les feuilles abîmées des endives et creuser le cône dur à leur base avec un petit couteau : c''est lui qui donne l''amertume.'),
  ('endives-jambon', 3, 'Cuire les endives 20 minutes à la vapeur.'),
  ('endives-jambon', 4, 'Les laisser tiédir puis les presser fermement entre les mains pour retirer un maximum d''eau, sinon le gratin sera détrempé.'),
  ('endives-jambon', 5, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes au fouet.'),
  ('endives-jambon', 6, 'Verser le lait petit à petit en fouettant sans arrêt, puis cuire 5 minutes jusqu''à épaississement.'),
  ('endives-jambon', 7, 'Assaisonner la béchamel de muscade, de sel et de poivre.'),
  ('endives-jambon', 8, 'Rouler chaque endive dans une tranche de jambon et les ranger côte à côte dans un plat allant au four.'),
  ('endives-jambon', 9, 'Napper de béchamel et couvrir d''emmental.'),
  ('endives-jambon', 10, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit bien gratiné.'),
  ('fajitas-poulet', 1, 'Dans un saladier, mélanger les lanières de poulet avec le paprika, le cumin et le jus du citron vert. Laisser mariner pendant la découpe des légumes.'),
  ('fajitas-poulet', 2, 'Épépiner les poivrons et les couper en lanières. Éplucher l''oignon rouge et l''émincer.'),
  ('fajitas-poulet', 3, 'Chauffer l''huile dans une grande poêle à feu vif.'),
  ('fajitas-poulet', 4, 'Faire sauter le poulet 5 à 6 minutes, jusqu''à ce qu''il soit doré et cuit à cœur. Le réserver.'),
  ('fajitas-poulet', 5, 'Dans la même poêle, faire sauter les poivrons et l''oignon 5 minutes à feu vif : ils doivent rester légèrement croquants.'),
  ('fajitas-poulet', 6, 'Remettre le poulet et mélanger 1 minute.'),
  ('fajitas-poulet', 7, 'Réchauffer les tortillas 20 secondes de chaque côté dans une poêle sèche à feu moyen.'),
  ('fajitas-poulet', 8, 'Râper le cheddar et laver la salade.'),
  ('fajitas-poulet', 9, 'Garnir chaque tortilla de poulet et de légumes, ajouter la crème, le cheddar et quelques feuilles de salade.'),
  ('fajitas-poulet', 10, 'Rouler les tortillas et servir aussitôt.'),
  ('falafels-four', 1, 'Préchauffer le four à 200 °C.'),
  ('falafels-four', 2, 'Égoutter et rincer les pois chiches, puis les sécher soigneusement dans un torchon : trop humides, les falafels s''écroulent.'),
  ('falafels-four', 3, 'Éplucher l''oignon et l''ail et les couper grossièrement.'),
  ('falafels-four', 4, 'Mixer les pois chiches avec l''oignon, l''ail, le persil, la coriandre, le cumin, la farine et le sel, par à-coups, en raclant les parois.'),
  ('falafels-four', 5, 'Arrêter quand la pâte est grossière et se tient quand on la presse dans la main.'),
  ('falafels-four', 6, 'Former des boulettes de la taille d''une noix et les aplatir légèrement.'),
  ('falafels-four', 7, 'Les poser sur une plaque huilée et les badigeonner d''huile.'),
  ('falafels-four', 8, 'Cuire 25 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et fermes.'),
  ('falafels-four', 9, 'Pendant ce temps, mélanger les yaourts avec le jus du citron et une pincée de sel.'),
  ('falafels-four', 10, 'Servir les falafels avec la sauce et la salade.'),
  ('farfalle-saumon-epinards', 1, 'Porter une grande casserole d''eau à ébullition et cuire les farfalle 10 à 12 minutes (voir le paquet).'),
  ('farfalle-saumon-epinards', 2, 'Pendant ce temps, prélever le zeste du citron, puis le presser.'),
  ('farfalle-saumon-epinards', 3, 'Laver et égoutter les épinards.'),
  ('farfalle-saumon-epinards', 4, 'Dans une poêle à feu moyen, faire chauffer la crème.'),
  ('farfalle-saumon-epinards', 5, 'Ajouter les épinards et remuer 3 minutes, jusqu''à ce qu''ils tombent.'),
  ('farfalle-saumon-epinards', 6, 'Ajouter le zeste et un filet de jus de citron, poivrer, puis retirer du feu.'),
  ('farfalle-saumon-epinards', 7, 'Égoutter les pâtes et les mélanger à la sauce.'),
  ('farfalle-saumon-epinards', 8, 'Ajouter le saumon en lanières au dernier moment, pour qu''il ne cuise pas, et servir aussitôt.'),
  ('filet-mignon-miel-moutarde', 1, 'Sortir le filet du réfrigérateur 20 minutes avant pour une cuisson régulière.'),
  ('filet-mignon-miel-moutarde', 2, 'Préchauffer le four à 190 °C.'),
  ('filet-mignon-miel-moutarde', 3, 'Éplucher les carottes et les couper en bâtonnets de même taille.'),
  ('filet-mignon-miel-moutarde', 4, 'Mélanger le miel et la moutarde dans un bol.'),
  ('filet-mignon-miel-moutarde', 5, 'Saler et poivrer le filet, puis le badigeonner de ce mélange sur toutes les faces.'),
  ('filet-mignon-miel-moutarde', 6, 'Poser le filet dans un plat allant au four et disposer les carottes autour.'),
  ('filet-mignon-miel-moutarde', 7, 'Arroser les carottes d''huile et parsemer le tout de thym.'),
  ('filet-mignon-miel-moutarde', 8, 'Enfourner 35 minutes en arrosant le filet de son jus à mi-cuisson : la viande doit être juste rosée au centre et les carottes tendres.'),
  ('filet-mignon-miel-moutarde', 9, 'Couvrir et laisser reposer 5 minutes hors du four : le jus se répartit dans la viande.'),
  ('filet-mignon-miel-moutarde', 10, 'Trancher en médaillons et servir avec les carottes et le jus du plat.'),
  ('frittata-legumes', 1, 'Préchauffer le four à 180 °C.'),
  ('frittata-legumes', 2, 'Éplucher et émincer l''oignon. Couper la courgette en fines demi-rondelles et les pommes de terre cuites en dés.'),
  ('frittata-legumes', 3, 'Chauffer l''huile à feu moyen dans une poêle allant au four.'),
  ('frittata-legumes', 4, 'Faire revenir l''oignon et la courgette 5 minutes.'),
  ('frittata-legumes', 5, 'Ajouter les pommes de terre et les faire dorer 3 minutes.'),
  ('frittata-legumes', 6, 'Battre les œufs avec l''emmental, du sel et du poivre.'),
  ('frittata-legumes', 7, 'Verser les œufs sur les légumes et répartir uniformément.'),
  ('frittata-legumes', 8, 'Cuire 5 minutes à feu doux sans remuer, jusqu''à ce que les bords prennent.'),
  ('frittata-legumes', 9, 'Glisser la poêle au four 12 à 15 minutes : le centre doit être pris et le dessus doré.'),
  ('frittata-legumes', 10, 'Laisser tiédir 2 minutes, puis faire glisser sur une planche et couper en parts.'),
  ('fusilli-pesto-poulet', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les fusilli 10 à 12 minutes (voir le paquet).'),
  ('fusilli-pesto-poulet', 2, 'Pendant ce temps, chauffer l''huile dans une poêle à feu moyen-vif.'),
  ('fusilli-pesto-poulet', 3, 'Dorer le poulet 8 minutes en remuant, jusqu''à ce qu''il soit cuit à cœur. Saler et poivrer.'),
  ('fusilli-pesto-poulet', 4, 'Couper les tomates cerises en deux.'),
  ('fusilli-pesto-poulet', 5, 'Prélever une petite louche d''eau de cuisson, puis égoutter les pâtes.'),
  ('fusilli-pesto-poulet', 6, 'Hors du feu, mélanger les pâtes avec le pesto ; ajouter un filet d''eau de cuisson si c''est trop épais.'),
  ('fusilli-pesto-poulet', 7, 'Ajouter le poulet et les tomates cerises et mélanger délicatement.'),
  ('fusilli-pesto-poulet', 8, 'Servir avec le parmesan râpé.'),
  ('galettes-pommes-de-terre', 1, 'Éplucher les pommes de terre et l''oignon et les râper avec une râpe à gros trous.'),
  ('galettes-pommes-de-terre', 2, 'Les mettre dans un torchon propre et presser fortement au-dessus de l''évier pour retirer le maximum d''eau : c''est le secret de galettes croustillantes.'),
  ('galettes-pommes-de-terre', 3, 'Dans un saladier, mélanger avec les œufs, la farine et le sel.'),
  ('galettes-pommes-de-terre', 4, 'Chauffer l''huile dans une grande poêle à feu moyen-vif.'),
  ('galettes-pommes-de-terre', 5, 'Déposer des cuillerées de mélange et les aplatir en galettes d''environ 1 cm.'),
  ('galettes-pommes-de-terre', 6, 'Cuire 4 minutes sans les bouger, jusqu''à ce que le dessous soit bien doré.'),
  ('galettes-pommes-de-terre', 7, 'Retourner et cuire encore 4 minutes.'),
  ('galettes-pommes-de-terre', 8, 'Égoutter sur du papier absorbant et garder au chaud pendant la cuisson des suivantes.'),
  ('galettes-pommes-de-terre', 9, 'Mélanger le fromage blanc avec la ciboulette ciselée et une pincée de sel.'),
  ('galettes-pommes-de-terre', 10, 'Servir les galettes chaudes avec la sauce et la salade.'),
  ('gaspacho', 1, 'Laver les légumes.'),
  ('gaspacho', 2, 'Couper les tomates en quartiers. Éplucher le concombre et le couper en morceaux.'),
  ('gaspacho', 3, 'Épépiner le poivron et le couper en morceaux. Éplucher l''oignon et l''ail.'),
  ('gaspacho', 4, 'Couper le pain en morceaux.'),
  ('gaspacho', 5, 'Mixer les légumes avec l''huile, le vinaigre, le pain et le sel pendant 2 minutes, jusqu''à obtenir une soupe bien lisse.'),
  ('gaspacho', 6, 'Goûter et rectifier l''assaisonnement ; détendre avec un peu d''eau froide si la soupe est trop épaisse.'),
  ('gaspacho', 7, 'Réfrigérer au moins 1 heure.'),
  ('gaspacho', 8, 'Mélanger avant de servir bien frais.'),
  ('gnocchis-epinards-lardons', 1, 'Laver et égoutter les épinards.'),
  ('gnocchis-epinards-lardons', 2, 'Dans une grande poêle à feu moyen, faire dorer les lardons à sec 4 minutes, jusqu''à ce qu''ils rendent leur graisse.'),
  ('gnocchis-epinards-lardons', 3, 'Ajouter les gnocchis et les faire dorer 6 minutes dans la graisse des lardons, en les retournant de temps en temps.'),
  ('gnocchis-epinards-lardons', 4, 'Ajouter les épinards et remuer 2 minutes, jusqu''à ce qu''ils tombent.'),
  ('gnocchis-epinards-lardons', 5, 'Verser la crème et le parmesan râpé.'),
  ('gnocchis-epinards-lardons', 6, 'Mélanger 1 minute pour bien napper les gnocchis.'),
  ('gnocchis-epinards-lardons', 7, 'Poivrer et servir aussitôt.'),
  ('gnocchis-pesto', 1, 'Couper les tomates cerises en deux.'),
  ('gnocchis-pesto', 2, 'Chauffer l''huile dans une poêle à feu moyen-vif.'),
  ('gnocchis-pesto', 3, 'Ajouter les gnocchis en une seule couche et les laisser dorer 3 minutes sans toucher.'),
  ('gnocchis-pesto', 4, 'Les retourner et poursuivre 3 à 5 minutes, jusqu''à ce qu''ils soient croustillants.'),
  ('gnocchis-pesto', 5, 'Ajouter les tomates cerises et cuire 2 minutes, juste pour qu''elles s''attendrissent.'),
  ('gnocchis-pesto', 6, 'Hors du feu, mélanger avec le pesto.'),
  ('gnocchis-pesto', 7, 'Servir avec le parmesan râpé.'),
  ('gratin-chou-fleur', 1, 'Préchauffer le four à 200 °C.'),
  ('gratin-chou-fleur', 2, 'Cuire les fleurettes de chou-fleur 10 minutes dans une casserole d''eau bouillante salée : elles doivent rester un peu fermes.'),
  ('gratin-chou-fleur', 3, 'Les égoutter soigneusement et les laisser sécher quelques minutes dans la passoire.'),
  ('gratin-chou-fleur', 4, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes au fouet.'),
  ('gratin-chou-fleur', 5, 'Verser le lait petit à petit en fouettant sans arrêt, puis cuire 5 minutes jusqu''à épaississement.'),
  ('gratin-chou-fleur', 6, 'Assaisonner de muscade, de sel et de poivre.'),
  ('gratin-chou-fleur', 7, 'Disposer le chou-fleur dans un plat à gratin et le napper de béchamel.'),
  ('gratin-chou-fleur', 8, 'Couvrir d''emmental.'),
  ('gratin-chou-fleur', 9, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit bien doré.'),
  ('gratin-courgettes', 1, 'Préchauffer le four à 190 °C.'),
  ('gratin-courgettes', 2, 'Laver les courgettes et les couper en rondelles fines. Peler et hacher l''ail.'),
  ('gratin-courgettes', 3, 'Chauffer l''huile dans une poêle à feu moyen.'),
  ('gratin-courgettes', 4, 'Faire revenir les courgettes avec l''ail 10 minutes, jusqu''à ce qu''elles aient rendu leur eau.'),
  ('gratin-courgettes', 5, 'Les égoutter dans une passoire : sans cela, le gratin rendrait du liquide.'),
  ('gratin-courgettes', 6, 'Battre les œufs avec la crème, saler et poivrer.'),
  ('gratin-courgettes', 7, 'Répartir les courgettes dans un plat à gratin.'),
  ('gratin-courgettes', 8, 'Verser le mélange œufs-crème et couvrir d''emmental.'),
  ('gratin-courgettes', 9, 'Enfourner 25 minutes, jusqu''à ce que l''appareil soit pris et le dessus doré.'),
  ('gratin-dauphinois', 1, 'Préchauffer le four à 180 °C.'),
  ('gratin-dauphinois', 2, 'Peler la gousse d''ail, la couper en deux et en frotter tout l''intérieur d''un plat à gratin. Le beurrer ensuite généreusement.'),
  ('gratin-dauphinois', 3, 'Éplucher les pommes de terre et les couper en rondelles fines d''environ 3 mm, sans les rincer : leur amidon épaissira la sauce.'),
  ('gratin-dauphinois', 4, 'Dans une grande casserole, verser le lait et la crème. Ajouter du sel, du poivre et la muscade.'),
  ('gratin-dauphinois', 5, 'Porter à frémissement à feu moyen, en surveillant pour que ça ne déborde pas.'),
  ('gratin-dauphinois', 6, 'Ajouter les pommes de terre et cuire 10 minutes à feu doux en remuant délicatement, jusqu''à ce que le liquide épaississe.'),
  ('gratin-dauphinois', 7, 'Verser le tout dans le plat et répartir les rondelles en couches régulières.'),
  ('gratin-dauphinois', 8, 'Enfourner 50 minutes, jusqu''à ce que le dessus soit doré et que la pointe d''un couteau traverse les pommes de terre sans résistance.'),
  ('gratin-dauphinois', 9, 'Laisser reposer 10 minutes avant de servir : le gratin se tiendra mieux.'),
  ('gratin-pates-brocoli', 1, 'Préchauffer le four à 200 °C.'),
  ('gratin-pates-brocoli', 2, 'Détailler le brocoli en petites fleurettes.'),
  ('gratin-pates-brocoli', 3, 'Porter une grande casserole d''eau salée à ébullition. Cuire les pâtes 4 minutes.'),
  ('gratin-pates-brocoli', 4, 'Ajouter le brocoli et cuire encore 4 minutes, puis égoutter le tout.'),
  ('gratin-pates-brocoli', 5, 'Battre la crème avec les œufs, la muscade, le sel et le poivre.'),
  ('gratin-pates-brocoli', 6, 'Verser les pâtes et le brocoli dans un plat à gratin.'),
  ('gratin-pates-brocoli', 7, 'Napper du mélange crème-œufs.'),
  ('gratin-pates-brocoli', 8, 'Couvrir d''emmental.'),
  ('gratin-pates-brocoli', 9, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit gratiné et l''appareil pris.'),
  ('gratin-poireaux-jambon', 1, 'Préchauffer le four à 200 °C.'),
  ('gratin-poireaux-jambon', 2, 'Couper la base et le haut vert foncé des poireaux, puis les couper en tronçons de 4 cm. Les rincer soigneusement.'),
  ('gratin-poireaux-jambon', 3, 'Cuire les poireaux 15 minutes à la vapeur, puis bien les égoutter.'),
  ('gratin-poireaux-jambon', 4, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes au fouet.'),
  ('gratin-poireaux-jambon', 5, 'Verser le lait petit à petit en fouettant sans arrêt, puis cuire 5 minutes jusqu''à épaississement.'),
  ('gratin-poireaux-jambon', 6, 'Assaisonner de muscade, de sel et de poivre.'),
  ('gratin-poireaux-jambon', 7, 'Couper le jambon en lanières.'),
  ('gratin-poireaux-jambon', 8, 'Disposer les poireaux et le jambon dans un plat à gratin.'),
  ('gratin-poireaux-jambon', 9, 'Napper de béchamel et couvrir d''emmental.'),
  ('gratin-poireaux-jambon', 10, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit doré.'),
  ('hachis-parmentier', 1, 'Éplucher les pommes de terre et les couper en morceaux de taille égale.'),
  ('hachis-parmentier', 2, 'Les mettre dans une casserole d''eau froide salée, porter à ébullition et cuire 20 minutes : la pointe d''un couteau doit s''y enfoncer facilement.'),
  ('hachis-parmentier', 3, 'Pendant ce temps, éplucher et émincer les oignons.'),
  ('hachis-parmentier', 4, 'Faire fondre la moitié du beurre dans une poêle à feu moyen et faire revenir les oignons 5 minutes.'),
  ('hachis-parmentier', 5, 'Ajouter la viande et le concentré de tomate et cuire 10 minutes en émiettant, jusqu''à ce que la viande soit bien colorée. Saler et poivrer.'),
  ('hachis-parmentier', 6, 'Préchauffer le four à 200 °C. Faire chauffer le lait.'),
  ('hachis-parmentier', 7, 'Égoutter les pommes de terre et les écraser avec le reste du beurre.'),
  ('hachis-parmentier', 8, 'Incorporer le lait chaud petit à petit jusqu''à obtenir une purée lisse. Saler et poivrer.'),
  ('hachis-parmentier', 9, 'Étaler la viande dans un plat à gratin, puis recouvrir de purée en lissant à la fourchette.'),
  ('hachis-parmentier', 10, 'Parsemer d''emmental.'),
  ('hachis-parmentier', 11, 'Enfourner 25 minutes, jusqu''à ce que le dessus soit bien doré.'),
  ('lasagnes-bolognaise', 1, 'Éplucher et hacher l''oignon et l''ail. Éplucher et râper la carotte.'),
  ('lasagnes-bolognaise', 2, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon, la carotte et l''ail 5 minutes.'),
  ('lasagnes-bolognaise', 3, 'Ajouter le bœuf et le faire colorer 5 minutes en l''émiettant.'),
  ('lasagnes-bolognaise', 4, 'Verser le coulis, saler, poivrer et laisser mijoter 20 minutes à feu doux.'),
  ('lasagnes-bolognaise', 5, 'Préchauffer le four à 180 °C.'),
  ('lasagnes-bolognaise', 6, 'Préparer la béchamel : faire fondre le beurre dans une casserole, ajouter la farine et remuer 2 minutes au fouet.'),
  ('lasagnes-bolognaise', 7, 'Verser le lait petit à petit en fouettant sans arrêt et cuire 5 minutes jusqu''à épaississement. Ajouter la muscade et saler.'),
  ('lasagnes-bolognaise', 8, 'Dans un plat allant au four, étaler une fine couche de sauce : elle empêche les pâtes d''attacher.'),
  ('lasagnes-bolognaise', 9, 'Alterner une couche de pâtes, de sauce et de béchamel, jusqu''à épuisement.'),
  ('lasagnes-bolognaise', 10, 'Terminer par la béchamel et l''emmental.'),
  ('lasagnes-bolognaise', 11, 'Enfourner 40 minutes, jusqu''à ce que le dessus soit doré et que les pâtes soient tendres sous la pointe d''un couteau.'),
  ('lasagnes-bolognaise', 12, 'Laisser reposer 10 minutes avant de couper, pour des parts nettes.'),
  ('lasagnes-epinards-ricotta', 1, 'Préchauffer le four à 180 °C.'),
  ('lasagnes-epinards-ricotta', 2, 'Peler et hacher l''ail. Laver les épinards.'),
  ('lasagnes-epinards-ricotta', 3, 'Faire tomber les épinards avec l''ail 3 à 4 minutes dans une poêle à feu moyen.'),
  ('lasagnes-epinards-ricotta', 4, 'Les égoutter dans une passoire en les pressant bien, puis les hacher grossièrement.'),
  ('lasagnes-epinards-ricotta', 5, 'Mélanger les épinards avec la ricotta, la moitié du parmesan, la muscade, du sel et du poivre.'),
  ('lasagnes-epinards-ricotta', 6, 'Dans un plat allant au four, étaler une couche de coulis.'),
  ('lasagnes-epinards-ricotta', 7, 'Alterner pâtes, coulis et mélange épinards-ricotta, jusqu''à épuisement.'),
  ('lasagnes-epinards-ricotta', 8, 'Terminer par une couche de pâtes et de coulis.'),
  ('lasagnes-epinards-ricotta', 9, 'Couper la mozzarella en tranches et la répartir sur le dessus, puis parsemer du reste de parmesan.'),
  ('lasagnes-epinards-ricotta', 10, 'Enfourner 40 minutes, jusqu''à ce que le dessus soit doré et bouillonnant.'),
  ('lasagnes-epinards-ricotta', 11, 'Laisser reposer 10 minutes avant de couper.'),
  ('lentilles-corail-dahl', 1, 'Rincer les lentilles dans une passoire jusqu''à ce que l''eau soit claire.'),
  ('lentilles-corail-dahl', 2, 'Éplucher et hacher l''oignon et l''ail. Peler le gingembre à la cuillère et le râper.'),
  ('lentilles-corail-dahl', 3, 'Chauffer l''huile dans une casserole à feu moyen.'),
  ('lentilles-corail-dahl', 4, 'Faire revenir l''oignon, l''ail et le gingembre 5 minutes, jusqu''à ce que l''oignon soit tendre.'),
  ('lentilles-corail-dahl', 5, 'Ajouter le curcuma et le cumin et remuer 1 minute.'),
  ('lentilles-corail-dahl', 6, 'Ajouter les lentilles, les tomates, le lait de coco et l''eau. Bien mélanger.'),
  ('lentilles-corail-dahl', 7, 'Porter à frémissement, puis cuire 20 à 25 minutes à feu doux en remuant souvent, car les lentilles corail attachent facilement.'),
  ('lentilles-corail-dahl', 8, 'Le dahl est prêt quand les lentilles se défont en purée. Ajouter un peu d''eau s''il est trop épais.'),
  ('lentilles-corail-dahl', 9, 'Ajouter un trait de jus de citron vert juste avant de servir.'),
  ('lentilles-vertes-legumes', 1, 'Rincer les lentilles.'),
  ('lentilles-vertes-legumes', 2, 'Éplucher l''oignon et les carottes. Couper l''oignon, les carottes et le céleri en petits dés. Écraser l''ail.'),
  ('lentilles-vertes-legumes', 3, 'Chauffer l''huile dans une casserole à feu moyen.'),
  ('lentilles-vertes-legumes', 4, 'Faire revenir l''oignon, les carottes et le céleri 5 minutes.'),
  ('lentilles-vertes-legumes', 5, 'Ajouter les lentilles, l''ail, le laurier, le thym, l''eau et le cube émietté.'),
  ('lentilles-vertes-legumes', 6, 'Porter à ébullition, puis baisser le feu.'),
  ('lentilles-vertes-legumes', 7, 'Cuire 30 minutes à petit frémissement, à demi couvert. Ne saler qu''en fin de cuisson : le sel durcit la peau des lentilles.'),
  ('lentilles-vertes-legumes', 8, 'Les lentilles doivent être tendres mais encore entières. Égoutter l''excédent de liquide si besoin et retirer le laurier.'),
  ('lentilles-vertes-legumes', 9, 'Saler et ajouter la moutarde au moment de servir.'),
  ('linguine-crevettes-ail', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les linguine 9 à 11 minutes (voir le paquet).'),
  ('linguine-crevettes-ail', 2, 'Pendant ce temps, prélever le zeste du citron et le presser. Ciseler le persil.'),
  ('linguine-crevettes-ail', 3, 'Mettre l''huile, l''ail émincé et le piment dans une grande poêle froide.'),
  ('linguine-crevettes-ail', 4, 'Chauffer à feu doux 2 minutes, sans laisser l''ail brunir : il deviendrait amer.'),
  ('linguine-crevettes-ail', 5, 'Monter à feu vif, ajouter les crevettes et les saisir 3 minutes, jusqu''à ce qu''elles soient roses.'),
  ('linguine-crevettes-ail', 6, 'Ajouter le zeste et le jus du citron.'),
  ('linguine-crevettes-ail', 7, 'Prélever une petite louche d''eau de cuisson, puis égoutter les pâtes.'),
  ('linguine-crevettes-ail', 8, 'Ajouter les pâtes et l''eau de cuisson dans la poêle et mélanger 1 minute pour bien enrober.'),
  ('linguine-crevettes-ail', 9, 'Parsemer de persil et servir aussitôt.'),
  ('macaronis-gratines', 1, 'Préchauffer le four à 200 °C.'),
  ('macaronis-gratines', 2, 'Cuire les macaronis dans une grande casserole d''eau bouillante salée 2 minutes de moins que l''indication du paquet : ils finiront de cuire au four. Les égoutter.'),
  ('macaronis-gratines', 3, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes au fouet.'),
  ('macaronis-gratines', 4, 'Verser le lait petit à petit en fouettant sans arrêt, puis cuire 5 minutes jusqu''à épaississement.'),
  ('macaronis-gratines', 5, 'Hors du feu, ajouter le cheddar et la muscade et remuer jusqu''à ce que le fromage fonde. Saler.'),
  ('macaronis-gratines', 6, 'Mélanger la sauce avec les pâtes.'),
  ('macaronis-gratines', 7, 'Verser dans un plat à gratin.'),
  ('macaronis-gratines', 8, 'Couvrir d''emmental, puis de chapelure.'),
  ('macaronis-gratines', 9, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit doré et croustillant.'),
  ('merguez-semoule-legumes', 1, 'Éplucher et émincer l''oignon. Éplucher les carottes et les couper en rondelles. Couper les courgettes en gros dés.'),
  ('merguez-semoule-legumes', 2, 'Dans une casserole, mettre les carottes, l''oignon, les tomates, le cumin, l''eau et le cube émietté.'),
  ('merguez-semoule-legumes', 3, 'Porter à ébullition, puis couvrir et cuire 10 minutes à feu moyen.'),
  ('merguez-semoule-legumes', 4, 'Ajouter les courgettes et cuire encore 10 minutes.'),
  ('merguez-semoule-legumes', 5, 'Rincer les pois chiches et les ajouter pendant les 5 dernières minutes.'),
  ('merguez-semoule-legumes', 6, 'Pendant ce temps, chauffer une poêle à feu moyen et cuire les merguez 10 à 12 minutes en les retournant régulièrement, jusqu''à ce qu''elles soient bien dorées.'),
  ('merguez-semoule-legumes', 7, 'Préparer la semoule : la verser dans un saladier et la couvrir du même volume d''eau bouillante.'),
  ('merguez-semoule-legumes', 8, 'Couvrir et laisser gonfler 5 minutes, puis l''égrener à la fourchette.'),
  ('merguez-semoule-legumes', 9, 'Servir la semoule avec les légumes, leur bouillon et les merguez, et la harissa à part.'),
  ('minestrone', 1, 'Éplucher l''oignon et les carottes. Couper l''oignon, les carottes et le céleri en petits dés, et la courgette en dés un peu plus gros.'),
  ('minestrone', 2, 'Chauffer l''huile dans un faitout à feu moyen.'),
  ('minestrone', 3, 'Faire revenir l''oignon, les carottes et le céleri 5 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('minestrone', 4, 'Ajouter la courgette, les tomates, l''eau et les cubes émiettés.'),
  ('minestrone', 5, 'Porter à ébullition, puis cuire 20 minutes à frémissement.'),
  ('minestrone', 6, 'Rincer les haricots et les ajouter avec les coquillettes.'),
  ('minestrone', 7, 'Cuire encore 10 minutes, jusqu''à ce que les pâtes soient tendres. Remuer de temps en temps pour qu''elles n''attachent pas.'),
  ('minestrone', 8, 'Goûter et rectifier l''assaisonnement.'),
  ('minestrone', 9, 'Servir avec le parmesan râpé et le basilic ciselé.'),
  ('moules-marinieres', 1, 'Rincer les moules à l''eau froide dans une passoire.'),
  ('moules-marinieres', 2, 'Jeter celles qui sont cassées ou qui restent ouvertes quand on les tapote : elles ne sont pas consommables.'),
  ('moules-marinieres', 3, 'Éplucher et hacher les échalotes. Ciseler le persil.'),
  ('moules-marinieres', 4, 'Dans une grande cocotte, faire fondre le beurre à feu moyen.'),
  ('moules-marinieres', 5, 'Ajouter les échalotes et les faire fondre 3 minutes, sans coloration.'),
  ('moules-marinieres', 6, 'Monter à feu vif, verser le vin et ajouter les moules.'),
  ('moules-marinieres', 7, 'Couvrir et cuire 6 à 8 minutes en secouant la cocotte deux ou trois fois, jusqu''à ce que toutes les moules soient ouvertes.'),
  ('moules-marinieres', 8, 'Ajouter le persil et la crème, poivrer et mélanger.'),
  ('moules-marinieres', 9, 'Jeter les moules restées fermées.'),
  ('moules-marinieres', 10, 'Servir aussitôt dans des bols avec le jus, et le pain pour saucer.'),
  ('mousse-chocolat', 1, 'Casser le chocolat en morceaux dans un bol.'),
  ('mousse-chocolat', 2, 'Poser le bol sur une casserole d''eau frémissante, sans qu''il touche l''eau, et faire fondre le chocolat en remuant.'),
  ('mousse-chocolat', 3, 'Retirer du feu et laisser tiédir 5 minutes : trop chaud, il cuirait les œufs.'),
  ('mousse-chocolat', 4, 'Séparer les blancs des jaunes, en veillant à ce qu''aucune trace de jaune ne tombe dans les blancs.'),
  ('mousse-chocolat', 5, 'Incorporer les jaunes un à un au chocolat tiède en mélangeant vivement.'),
  ('mousse-chocolat', 6, 'Monter les blancs en neige dans un grand saladier propre et sec.'),
  ('mousse-chocolat', 7, 'Quand ils commencent à mousser, ajouter le sucre en pluie et continuer jusqu''à ce qu''ils soient fermes et brillants.'),
  ('mousse-chocolat', 8, 'Incorporer un tiers des blancs au chocolat en fouettant pour l''assouplir.'),
  ('mousse-chocolat', 9, 'Ajouter le reste des blancs délicatement à la spatule, en soulevant la masse, jusqu''à ce qu''il n''y ait plus de traces blanches.'),
  ('mousse-chocolat', 10, 'Répartir dans des ramequins ou un saladier et réfrigérer au moins 4 heures.'),
  ('nouilles-sautees-tofu', 1, 'Réhydrater les nouilles dans un saladier d''eau chaude 5 à 8 minutes (voir le paquet), jusqu''à ce qu''elles soient souples.'),
  ('nouilles-sautees-tofu', 2, 'Les égoutter et les rincer à l''eau froide pour qu''elles ne collent pas.'),
  ('nouilles-sautees-tofu', 3, 'Éplucher les carottes et les couper en julienne. Épépiner le poivron et le couper en lanières. Éplucher l''oignon et l''émincer.'),
  ('nouilles-sautees-tofu', 4, 'Peler le gingembre et le râper. Éponger le tofu et le couper en cubes.'),
  ('nouilles-sautees-tofu', 5, 'Chauffer la moitié de l''huile dans un wok ou une grande poêle à feu vif.'),
  ('nouilles-sautees-tofu', 6, 'Dorer le tofu 5 minutes en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces. Le réserver.'),
  ('nouilles-sautees-tofu', 7, 'Ajouter le reste d''huile et faire sauter les légumes et le gingembre 4 minutes à feu vif : ils doivent rester croquants.'),
  ('nouilles-sautees-tofu', 8, 'Ajouter les nouilles, le tofu, la sauce soja et le sucre.'),
  ('nouilles-sautees-tofu', 9, 'Mélanger 2 minutes à feu vif pour bien enrober.'),
  ('nouilles-sautees-tofu', 10, 'Concasser les cacahuètes, en parsemer le plat et servir.'),
  ('oeufs-cocotte', 1, 'Préchauffer le four à 180 °C et faire chauffer de l''eau.'),
  ('oeufs-cocotte', 2, 'Beurrer 4 ramequins avec une partie du beurre.'),
  ('oeufs-cocotte', 3, 'Répartir la crème et les dés de jambon dans les ramequins.'),
  ('oeufs-cocotte', 4, 'Casser délicatement un œuf dans chaque ramequin, sans crever le jaune. Saler et poivrer.'),
  ('oeufs-cocotte', 5, 'Poser les ramequins dans un plat allant au four et verser de l''eau chaude jusqu''à mi-hauteur : l''eau chaude autour des ramequins garde les œufs moelleux.'),
  ('oeufs-cocotte', 6, 'Enfourner 12 minutes : le blanc doit être pris et le jaune encore coulant.'),
  ('oeufs-cocotte', 7, 'Pendant ce temps, couper le pain en mouillettes, les tartiner du reste de beurre et les faire griller.'),
  ('oeufs-cocotte', 8, 'Ciseler la ciboulette et en parsemer les œufs.'),
  ('oeufs-cocotte', 9, 'Servir aussitôt avec les mouillettes.'),
  ('omelette-champignons', 1, 'Couper le bout terreux des champignons et les émincer s''ils ne le sont pas déjà. Ciseler le persil.'),
  ('omelette-champignons', 2, 'Faire fondre le beurre dans une poêle à feu moyen-vif.'),
  ('omelette-champignons', 3, 'Ajouter les champignons et les faire dorer 5 minutes, jusqu''à ce que leur eau soit évaporée. Saler.'),
  ('omelette-champignons', 4, 'Battre les œufs avec la crème, du sel et du poivre, juste assez pour mélanger blancs et jaunes.'),
  ('omelette-champignons', 5, 'Baisser à feu doux et verser les œufs sur les champignons.'),
  ('omelette-champignons', 6, 'Pendant 2 à 3 minutes, ramener les bords vers le centre avec une spatule pour que l''œuf liquide coule sur le fond.'),
  ('omelette-champignons', 7, 'Laisser cuire sans toucher jusqu''à ce que le dessus soit encore légèrement baveux.'),
  ('omelette-champignons', 8, 'Plier l''omelette en deux et la faire glisser sur une assiette.'),
  ('omelette-champignons', 9, 'Parsemer de persil et servir aussitôt.'),
  ('one-pot-pasta-legumes', 1, 'Laver la courgette et la couper en dés. Éplucher et émincer l''oignon et l''ail.'),
  ('one-pot-pasta-legumes', 2, 'Couper les tomates cerises en deux.'),
  ('one-pot-pasta-legumes', 3, 'Mettre les pâtes, les légumes et l''ail dans une grande casserole.'),
  ('one-pot-pasta-legumes', 4, 'Émietter le cube par-dessus et verser l''eau : les pâtes doivent être couvertes de liquide.'),
  ('one-pot-pasta-legumes', 5, 'Porter à ébullition à feu vif.'),
  ('one-pot-pasta-legumes', 6, 'Cuire 12 minutes à feu moyen en remuant souvent, pour que les pâtes n''attachent pas au fond.'),
  ('one-pot-pasta-legumes', 7, 'Quand il ne reste presque plus de liquide et que les pâtes sont tendres, retirer du feu. Goûter et saler si besoin.'),
  ('one-pot-pasta-legumes', 8, 'Ajouter le basilic ciselé et le parmesan râpé, mélanger : l''amidon des pâtes forme une sauce crémeuse.'),
  ('one-pot-pasta-legumes', 9, 'Servir aussitôt.'),
  ('paella-poulet-chorizo', 1, 'Éplucher et émincer l''oignon et l''ail. Épépiner les poivrons et les couper en lanières.'),
  ('paella-poulet-chorizo', 2, 'Dissoudre les cubes dans l''eau chaude.'),
  ('paella-poulet-chorizo', 3, 'Chauffer l''huile dans une grande poêle à feu moyen-vif.'),
  ('paella-poulet-chorizo', 4, 'Dorer les cuisses 8 à 10 minutes en les retournant, jusqu''à ce que la peau soit bien colorée.'),
  ('paella-poulet-chorizo', 5, 'Ajouter le chorizo 2 minutes, puis réserver le poulet et le chorizo sur une assiette.'),
  ('paella-poulet-chorizo', 6, 'Dans la même poêle, faire revenir l''oignon, l''ail et les poivrons 5 minutes à feu moyen.'),
  ('paella-poulet-chorizo', 7, 'Ajouter le riz et remuer 2 minutes pour bien l''enrober de matière grasse.'),
  ('paella-poulet-chorizo', 8, 'Ajouter le curcuma et le paprika et mélanger.'),
  ('paella-poulet-chorizo', 9, 'Verser le bouillon, remettre le poulet et le chorizo, et répartir le riz uniformément.'),
  ('paella-poulet-chorizo', 10, 'Cuire 20 minutes à feu moyen-doux sans remuer : une fine croûte doit se former au fond.'),
  ('paella-poulet-chorizo', 11, 'Enfoncer les crevettes et les petits pois dans le riz et cuire encore 10 minutes, jusqu''à ce que le liquide soit absorbé et les crevettes roses.'),
  ('paella-poulet-chorizo', 12, 'Couvrir et laisser reposer 5 minutes hors du feu, puis servir avec des quartiers de citron.'),
  ('pancakes', 1, 'Dans un saladier, mélanger la farine, le sucre et la levure.'),
  ('pancakes', 2, 'Ajouter les œufs et commencer à mélanger au fouet.'),
  ('pancakes', 3, 'Verser le lait petit à petit en fouettant, pour éviter les grumeaux.'),
  ('pancakes', 4, 'Ajouter le beurre fondu et mélanger : la pâte doit être épaisse et lisse.'),
  ('pancakes', 5, 'Laisser reposer 10 minutes.'),
  ('pancakes', 6, 'Chauffer une poêle à feu moyen et la graisser très légèrement.'),
  ('pancakes', 7, 'Verser une petite louche de pâte par pancake, en les espaçant.'),
  ('pancakes', 8, 'Cuire 1 à 2 minutes, jusqu''à ce que des bulles apparaissent à la surface.'),
  ('pancakes', 9, 'Retourner et cuire encore 1 minute, jusqu''à ce que les deux faces soient dorées.'),
  ('pancakes', 10, 'Servir chaud avec le sirop d''érable.'),
  ('papillotes-saumon-legumes', 1, 'Préchauffer le four à 200 °C.'),
  ('papillotes-saumon-legumes', 2, 'Si vous servez du riz, le cuire dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('papillotes-saumon-legumes', 3, 'Laver la courgette, éplucher les carottes et les couper en julienne.'),
  ('papillotes-saumon-legumes', 4, 'Couper le citron en rondelles.'),
  ('papillotes-saumon-legumes', 5, 'Découper 4 grandes feuilles de papier cuisson et répartir les légumes au centre de chacune.'),
  ('papillotes-saumon-legumes', 6, 'Poser un pavé de saumon sur chaque lit de légumes.'),
  ('papillotes-saumon-legumes', 7, 'Ajouter une rondelle de citron, le thym, un filet d''huile, du sel et du poivre.'),
  ('papillotes-saumon-legumes', 8, 'Refermer les papillotes en repliant les bords plusieurs fois pour qu''elles soient bien étanches : la vapeur cuit le poisson.'),
  ('papillotes-saumon-legumes', 9, 'Poser les papillotes sur la plaque du four et enfourner 18 minutes.'),
  ('papillotes-saumon-legumes', 10, 'Ouvrir les papillotes à table : la chair doit être rosée et s''effeuiller facilement. Servir avec le riz.'),
  ('patates-douces-feta-pois-chiches', 1, 'Préchauffer le four à 200 °C.'),
  ('patates-douces-feta-pois-chiches', 2, 'Éplucher les patates douces et les couper en cubes d''environ 2 cm.'),
  ('patates-douces-feta-pois-chiches', 3, 'Rincer, égoutter et sécher les pois chiches.'),
  ('patates-douces-feta-pois-chiches', 4, 'Sur la plaque du four, mélanger les patates douces et les pois chiches avec l''huile, le cumin, le paprika et le sel.'),
  ('patates-douces-feta-pois-chiches', 5, 'Les étaler en une seule couche, sans les entasser, pour qu''ils rôtissent au lieu de ramollir.'),
  ('patates-douces-feta-pois-chiches', 6, 'Rôtir 35 minutes en remuant à mi-cuisson, jusqu''à ce que les patates douces soient tendres et caramélisées sur les bords.'),
  ('patates-douces-feta-pois-chiches', 7, 'Émietter la feta et ciseler le persil.'),
  ('patates-douces-feta-pois-chiches', 8, 'Parsemer de feta, arroser de jus de citron et ajouter le persil au moment de servir.'),
  ('pates-thon-tomate', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les pâtes 9 à 11 minutes (voir le paquet).'),
  ('pates-thon-tomate', 2, 'Pendant ce temps, peler et émincer l''ail.'),
  ('pates-thon-tomate', 3, 'Chauffer l''huile dans une poêle à feu moyen et faire revenir l''ail 1 minute, sans le laisser brunir.'),
  ('pates-thon-tomate', 4, 'Verser le coulis et laisser mijoter 10 minutes à feu doux. Saler et poivrer.'),
  ('pates-thon-tomate', 5, 'Égoutter et émietter le thon.'),
  ('pates-thon-tomate', 6, 'Ajouter le thon, les olives et les câpres et réchauffer 2 minutes.'),
  ('pates-thon-tomate', 7, 'Égoutter les pâtes et les mélanger à la sauce.'),
  ('pates-tomate-basilic', 1, 'Éplucher et hacher l''oignon. Peler et écraser l''ail.'),
  ('pates-tomate-basilic', 2, 'Chauffer l''huile dans une casserole à feu moyen.'),
  ('pates-tomate-basilic', 3, 'Faire fondre l''oignon 5 minutes, jusqu''à ce qu''il soit translucide.'),
  ('pates-tomate-basilic', 4, 'Ajouter l''ail et remuer 1 minute.'),
  ('pates-tomate-basilic', 5, 'Verser le coulis, saler et poivrer.'),
  ('pates-tomate-basilic', 6, 'Laisser mijoter 15 minutes à feu doux, à demi couvert, pour que la sauce épaississe.'),
  ('pates-tomate-basilic', 7, 'Pendant ce temps, cuire les pâtes dans une grande casserole d''eau bouillante salée 9 à 11 minutes (voir le paquet).'),
  ('pates-tomate-basilic', 8, 'Égoutter les pâtes et les mélanger à la sauce.'),
  ('pates-tomate-basilic', 9, 'Ajouter le basilic ciselé et le parmesan râpé au moment de servir.'),
  ('penne-arrabbiata', 1, 'Peler et émincer l''ail. Hacher le piment s''il est frais.'),
  ('penne-arrabbiata', 2, 'Dans une poêle, chauffer l''huile à feu doux avec l''ail et le piment 2 minutes, sans les laisser colorer.'),
  ('penne-arrabbiata', 3, 'Ajouter les tomates et saler.'),
  ('penne-arrabbiata', 4, 'Laisser réduire 15 minutes à feu moyen-doux, jusqu''à ce que la sauce épaississe.'),
  ('penne-arrabbiata', 5, 'Pendant ce temps, cuire les penne dans une grande casserole d''eau bouillante salée 10 à 12 minutes (voir le paquet), jusqu''à ce qu''elles soient al dente.'),
  ('penne-arrabbiata', 6, 'Égoutter les pâtes et les verser dans la sauce.'),
  ('penne-arrabbiata', 7, 'Mélanger 1 minute à feu moyen pour que la sauce enrobe bien.'),
  ('penne-arrabbiata', 8, 'Parsemer de persil et de parmesan râpé.'),
  ('penne-courgettes-feta', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les penne 10 à 12 minutes (voir le paquet).'),
  ('penne-courgettes-feta', 2, 'Pendant ce temps, laver les courgettes et les couper en rondelles fines.'),
  ('penne-courgettes-feta', 3, 'Chauffer l''huile dans une grande poêle à feu moyen-vif.'),
  ('penne-courgettes-feta', 4, 'Faire dorer les courgettes 8 minutes en les remuant de temps en temps. Saler et poivrer.'),
  ('penne-courgettes-feta', 5, 'Prélever le zeste du citron et le presser.'),
  ('penne-courgettes-feta', 6, 'Égoutter les pâtes et les mélanger aux courgettes avec le zeste et le jus de citron.'),
  ('penne-courgettes-feta', 7, 'Émietter la feta et ciseler la menthe.'),
  ('penne-courgettes-feta', 8, 'Les ajouter au moment de servir.'),
  ('poelee-saucisses-lentilles', 1, 'Rincer les lentilles.'),
  ('poelee-saucisses-lentilles', 2, 'Éplucher et émincer l''oignon. Éplucher les carottes et les couper en rondelles.'),
  ('poelee-saucisses-lentilles', 3, 'Dans une cocotte à feu moyen, faire dorer les saucisses 5 minutes en les retournant. Les réserver.'),
  ('poelee-saucisses-lentilles', 4, 'Dans la même cocotte, faire revenir l''oignon et les carottes 5 minutes dans la graisse des saucisses.'),
  ('poelee-saucisses-lentilles', 5, 'Ajouter les lentilles, le thym, le laurier et l''eau.'),
  ('poelee-saucisses-lentilles', 6, 'Remettre les saucisses et porter à ébullition.'),
  ('poelee-saucisses-lentilles', 7, 'Cuire 30 minutes à frémissement, à demi couvert, jusqu''à ce que les lentilles soient tendres.'),
  ('poelee-saucisses-lentilles', 8, 'Retirer le laurier et servir avec un peu de moutarde.'),
  ('pommes-de-terre-farcies', 1, 'Préchauffer le four à 200 °C.'),
  ('pommes-de-terre-farcies', 2, 'Laver et brosser les pommes de terre, puis les piquer plusieurs fois à la fourchette.'),
  ('pommes-de-terre-farcies', 3, 'Les cuire entières 40 minutes sur la plaque du four : la pointe d''un couteau doit s''y enfoncer facilement.'),
  ('pommes-de-terre-farcies', 4, 'Pendant ce temps, éplucher et émincer l''oignon.'),
  ('pommes-de-terre-farcies', 5, 'Le faire fondre 5 minutes dans une poêle à feu doux.'),
  ('pommes-de-terre-farcies', 6, 'Couper le jambon en petits dés.'),
  ('pommes-de-terre-farcies', 7, 'Couper les pommes de terre en deux dans la longueur et retirer la chair avec une cuillère, en laissant une fine épaisseur contre la peau.'),
  ('pommes-de-terre-farcies', 8, 'Écraser la chair avec la crème, le jambon et l''oignon. Saler et poivrer.'),
  ('pommes-de-terre-farcies', 9, 'Remplir les peaux de cette farce et couvrir d''emmental.'),
  ('pommes-de-terre-farcies', 10, 'Remettre au four 15 minutes, jusqu''à ce que le fromage soit doré.'),
  ('pommes-de-terre-oeufs-plat', 1, 'Éplucher les pommes de terre et les couper en dés d''environ 1,5 cm.'),
  ('pommes-de-terre-oeufs-plat', 2, 'Les sécher dans un torchon : elles doreront mieux.'),
  ('pommes-de-terre-oeufs-plat', 3, 'Éplucher et émincer l''oignon.'),
  ('pommes-de-terre-oeufs-plat', 4, 'Chauffer les deux tiers de l''huile dans une grande poêle à feu moyen-vif.'),
  ('pommes-de-terre-oeufs-plat', 5, 'Faire sauter les pommes de terre 20 minutes en remuant régulièrement, jusqu''à ce qu''elles soient dorées et tendres.'),
  ('pommes-de-terre-oeufs-plat', 6, 'Ajouter l''oignon à mi-cuisson. Saler en fin de cuisson.'),
  ('pommes-de-terre-oeufs-plat', 7, 'Chauffer le reste d''huile dans une autre poêle à feu moyen.'),
  ('pommes-de-terre-oeufs-plat', 8, 'Y casser les œufs et les cuire 3 à 4 minutes, jusqu''à ce que le blanc soit pris et le jaune encore coulant.'),
  ('pommes-de-terre-oeufs-plat', 9, 'Servir les pommes de terre surmontées des œufs, parsemées de persil, avec la salade.'),
  ('porc-caramel', 1, 'Lancer le riz dans une casserole d''eau bouillante, 10 à 12 minutes, puis l''égoutter.'),
  ('porc-caramel', 2, 'Éplucher et émincer les oignons. Peler et hacher l''ail. Peler et râper le gingembre.'),
  ('porc-caramel', 3, 'Chauffer l''huile dans une sauteuse à feu vif.'),
  ('porc-caramel', 4, 'Dorer le porc 5 minutes en remuant. Le réserver.'),
  ('porc-caramel', 5, 'Baisser à feu moyen et ajouter le sucre.'),
  ('porc-caramel', 6, 'Le laisser fondre sans remuer, en secouant doucement la sauteuse, jusqu''à obtenir un caramel blond. Surveiller : il brûle en quelques secondes.'),
  ('porc-caramel', 7, 'Ajouter aussitôt les oignons, l''ail et le gingembre et remuer 2 minutes.'),
  ('porc-caramel', 8, 'Remettre le porc, ajouter la sauce soja et l''eau.'),
  ('porc-caramel', 9, 'Laisser mijoter 25 minutes à feu doux, à découvert, en remuant de temps en temps, jusqu''à ce que la sauce soit sirupeuse et nappe la viande.'),
  ('porc-caramel', 10, 'Servir avec le riz.'),
  ('porc-moutarde', 1, 'Sortir le filet du réfrigérateur 15 minutes avant.'),
  ('porc-moutarde', 2, 'Éplucher et émincer les échalotes.'),
  ('porc-moutarde', 3, 'Faire fondre le beurre dans une cocotte à feu moyen-vif.'),
  ('porc-moutarde', 4, 'Dorer le filet mignon entier 6 à 8 minutes en le tournant, jusqu''à ce qu''il soit coloré sur toutes les faces.'),
  ('porc-moutarde', 5, 'Ajouter les échalotes et les faire revenir 2 minutes.'),
  ('porc-moutarde', 6, 'Verser le vin blanc en grattant le fond pour décoller les sucs.'),
  ('porc-moutarde', 7, 'Couvrir et cuire 20 minutes à feu doux, en retournant la viande à mi-cuisson.'),
  ('porc-moutarde', 8, 'Si vous servez des pâtes, les cuire pendant ce temps dans une grande casserole d''eau bouillante.'),
  ('porc-moutarde', 9, 'Retirer la viande sur une planche. Ajouter la crème et la moutarde dans la cocotte et laisser réduire 5 minutes, jusqu''à ce que la sauce nappe.'),
  ('porc-moutarde', 10, 'Trancher le filet en médaillons et le napper de sauce.'),
  ('potee-chou-saucisses', 1, 'Retirer les feuilles abîmées du chou et le couper en quartiers en enlevant le cœur dur.'),
  ('potee-chou-saucisses', 2, 'Plonger le chou 5 minutes dans un faitout d''eau bouillante : cela le rend plus digeste. L''égoutter et vider le faitout.'),
  ('potee-chou-saucisses', 3, 'Éplucher et émincer les oignons. Éplucher les carottes et les couper en tronçons. Éplucher les pommes de terre et couper en deux les plus grosses.'),
  ('potee-chou-saucisses', 4, 'Dans le faitout, faire revenir les lardons et les oignons 5 minutes à feu moyen.'),
  ('potee-chou-saucisses', 5, 'Ajouter le chou, les carottes, le laurier, l''eau et les cubes émiettés.'),
  ('potee-chou-saucisses', 6, 'Porter à ébullition, puis couvrir et cuire 40 minutes à feu doux.'),
  ('potee-chou-saucisses', 7, 'Ajouter les pommes de terre et les saucisses.'),
  ('potee-chou-saucisses', 8, 'Cuire encore 30 minutes, jusqu''à ce que les pommes de terre soient tendres.'),
  ('potee-chou-saucisses', 9, 'Poivrer et servir avec un peu de bouillon.'),
  ('poulet-basquaise', 1, 'Éplucher et émincer les oignons et l''ail. Épépiner les poivrons et les couper en lanières. Couper les tomates en morceaux.'),
  ('poulet-basquaise', 2, 'Chauffer l''huile dans une cocotte à feu moyen-vif.'),
  ('poulet-basquaise', 3, 'Dorer les cuisses 5 minutes côté peau, puis 5 minutes de l''autre côté. Les réserver.'),
  ('poulet-basquaise', 4, 'Dans la même cocotte, faire revenir les oignons, les poivrons et l''ail 10 minutes à feu moyen, jusqu''à ce qu''ils soient tendres.'),
  ('poulet-basquaise', 5, 'Ajouter les tomates, le paprika et le thym. Saler et poivrer.'),
  ('poulet-basquaise', 6, 'Remettre le poulet en l''enfonçant dans les légumes.'),
  ('poulet-basquaise', 7, 'Couvrir et laisser mijoter 35 minutes à feu doux : la chair doit se détacher facilement de l''os.'),
  ('poulet-basquaise', 8, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('poulet-basquaise', 9, 'Servir le poulet et sa sauce avec le riz.'),
  ('poulet-citron-olives', 1, 'Éplucher et émincer les oignons et l''ail. Peler et râper le gingembre.'),
  ('poulet-citron-olives', 2, 'Presser un citron et couper l''autre en quartiers.'),
  ('poulet-citron-olives', 3, 'Chauffer l''huile dans une cocotte à feu moyen-vif.'),
  ('poulet-citron-olives', 4, 'Dorer les cuisses 5 minutes par face. Les réserver.'),
  ('poulet-citron-olives', 5, 'Baisser à feu moyen et faire revenir les oignons, l''ail, le gingembre, le cumin et le curcuma 5 minutes.'),
  ('poulet-citron-olives', 6, 'Remettre le poulet, ajouter l''eau, le cube émietté, le jus du citron et les quartiers de l''autre.'),
  ('poulet-citron-olives', 7, 'Couvrir et laisser mijoter 25 minutes à feu doux.'),
  ('poulet-citron-olives', 8, 'Ajouter les olives et cuire encore 10 minutes à découvert, pour que la sauce réduise un peu.'),
  ('poulet-citron-olives', 9, 'Préparer la semoule : la couvrir du même volume d''eau bouillante, couvrir 5 minutes, puis l''égrener à la fourchette.'),
  ('poulet-citron-olives', 10, 'Servir le poulet sur la semoule, parsemé de coriandre ciselée.'),
  ('poulet-curry-coco', 1, 'Lancer le riz dans une casserole d''eau bouillante, 11 à 12 minutes, puis l''égoutter.'),
  ('poulet-curry-coco', 2, 'Éplucher et émincer l''oignon. Épépiner le poivron et le couper en lanières.'),
  ('poulet-curry-coco', 3, 'Chauffer l''huile dans une sauteuse à feu moyen.'),
  ('poulet-curry-coco', 4, 'Faire revenir l''oignon et le poivron 5 minutes.'),
  ('poulet-curry-coco', 5, 'Monter le feu, ajouter le poulet et le faire dorer 5 minutes.'),
  ('poulet-curry-coco', 6, 'Ajouter la pâte de curry et remuer 1 minute, jusqu''à ce qu''elle embaume.'),
  ('poulet-curry-coco', 7, 'Verser le lait de coco et porter à frémissement.'),
  ('poulet-curry-coco', 8, 'Laisser mijoter 15 minutes à feu doux, jusqu''à ce que le poulet soit cuit à cœur et la sauce légèrement épaissie.'),
  ('poulet-curry-coco', 9, 'Servir avec le riz et la coriandre ciselée.'),
  ('poulet-grenailles-thym', 1, 'Sortir le poulet du réfrigérateur 15 minutes avant. Préchauffer le four à 200 °C.'),
  ('poulet-grenailles-thym', 2, 'Laver les grenailles sans les éplucher et couper en deux les plus grosses, pour qu''elles cuisent en même temps.'),
  ('poulet-grenailles-thym', 3, 'Dans un grand plat allant au four, mélanger les grenailles avec l''huile, les gousses d''ail non épluchées, le thym, du sel et du poivre.'),
  ('poulet-grenailles-thym', 4, 'Éponger les cuisses et les poser sur les pommes de terre, peau vers le haut. Les saler et les poivrer.'),
  ('poulet-grenailles-thym', 5, 'Couper le citron en quartiers et les glisser entre les morceaux.'),
  ('poulet-grenailles-thym', 6, 'Rôtir 45 minutes en remuant les pommes de terre à mi-cuisson.'),
  ('poulet-grenailles-thym', 7, 'Vérifier la cuisson : la peau doit être dorée et croustillante, et le jus qui s''écoule de la cuisse piquée doit être clair.'),
  ('poulet-grenailles-thym', 8, 'Servir en pressant les gousses d''ail confites et le citron rôti sur le poulet.'),
  ('poulet-miel-soja', 1, 'Lancer le riz dans une casserole d''eau bouillante, 10 à 12 minutes, puis l''égoutter.'),
  ('poulet-miel-soja', 2, 'Détailler le brocoli en bouquets et le cuire 6 minutes à la vapeur.'),
  ('poulet-miel-soja', 3, 'Peler et hacher l''ail. Peler et râper le gingembre.'),
  ('poulet-miel-soja', 4, 'Mélanger la sauce soja et le miel dans un bol.'),
  ('poulet-miel-soja', 5, 'Chauffer l''huile dans une poêle à feu moyen-vif.'),
  ('poulet-miel-soja', 6, 'Dorer le poulet 8 minutes en remuant, jusqu''à ce qu''il soit cuit à cœur.'),
  ('poulet-miel-soja', 7, 'Ajouter l''ail et le gingembre et remuer 30 secondes.'),
  ('poulet-miel-soja', 8, 'Verser le mélange soja-miel et laisser laquer 3 minutes en remuant, jusqu''à ce que la sauce devienne sirupeuse et brillante.'),
  ('poulet-miel-soja', 9, 'Parsemer de sésame et servir avec le riz et le brocoli.'),
  ('poulet-roti-legumes', 1, 'Sortir le poulet du réfrigérateur 15 minutes avant. Préchauffer le four à 200 °C.'),
  ('poulet-roti-legumes', 2, 'Éplucher les pommes de terre et les couper en quartiers. Éplucher les carottes et les couper en bâtonnets. Éplucher les oignons rouges et les couper en quartiers.'),
  ('poulet-roti-legumes', 3, 'Dans un grand plat allant au four, mélanger les légumes et les gousses d''ail non épluchées avec l''huile, les herbes, du sel et du poivre.'),
  ('poulet-roti-legumes', 4, 'Étaler les légumes en une couche régulière.'),
  ('poulet-roti-legumes', 5, 'Éponger les cuisses, les poser sur les légumes peau vers le haut, puis les saler et les poivrer.'),
  ('poulet-roti-legumes', 6, 'Enfourner 50 minutes en retournant les légumes à mi-cuisson, sans déplacer le poulet.'),
  ('poulet-roti-legumes', 7, 'Vérifier la cuisson : la peau doit être dorée et le jus qui s''écoule de la cuisse piquée doit être clair.'),
  ('poulet-roti-legumes', 8, 'Laisser reposer 5 minutes hors du four, puis servir le poulet sur les légumes avec le jus du plat.'),
  ('poulet-yaourt-epices-basmati', 1, 'Peler et hacher l''ail. Peler et râper le gingembre.'),
  ('poulet-yaourt-epices-basmati', 2, 'Dans un saladier, mélanger le yaourt avec le curry, le curcuma, le gingembre, l''ail et le sel.'),
  ('poulet-yaourt-epices-basmati', 3, 'Ajouter le poulet, bien l''enrober et laisser mariner au moins 15 minutes : le yaourt attendrit la viande.'),
  ('poulet-yaourt-epices-basmati', 4, 'Rincer le riz basmati dans une passoire jusqu''à ce que l''eau soit claire.'),
  ('poulet-yaourt-epices-basmati', 5, 'Le cuire dans une casserole d''eau bouillante 10 à 11 minutes, puis l''égoutter.'),
  ('poulet-yaourt-epices-basmati', 6, 'Éplucher et émincer l''oignon.'),
  ('poulet-yaourt-epices-basmati', 7, 'Chauffer l''huile dans une poêle à feu moyen et faire revenir l''oignon 5 minutes.'),
  ('poulet-yaourt-epices-basmati', 8, 'Ajouter le poulet et sa marinade.'),
  ('poulet-yaourt-epices-basmati', 9, 'Cuire 12 minutes à feu moyen en remuant, jusqu''à ce que le poulet soit cuit à cœur et la sauce épaissie.'),
  ('poulet-yaourt-epices-basmati', 10, 'Servir avec le riz et la coriandre ciselée.'),
  ('puree-saucisses', 1, 'Éplucher les pommes de terre et les couper en morceaux de taille égale.'),
  ('puree-saucisses', 2, 'Les mettre dans une casserole d''eau froide salée et porter à ébullition.'),
  ('puree-saucisses', 3, 'Cuire 20 minutes, jusqu''à ce que la pointe d''un couteau s''y enfonce sans résistance.'),
  ('puree-saucisses', 4, 'Pendant ce temps, chauffer une poêle à feu moyen et cuire les saucisses 15 minutes en les retournant régulièrement.'),
  ('puree-saucisses', 5, 'Si vous utilisez l''oignon, l''émincer et l''ajouter autour des saucisses pendant les 10 dernières minutes.'),
  ('puree-saucisses', 6, 'Faire chauffer le lait.'),
  ('puree-saucisses', 7, 'Égoutter les pommes de terre et les écraser au presse-purée avec le beurre.'),
  ('puree-saucisses', 8, 'Incorporer le lait chaud petit à petit jusqu''à la texture souhaitée.'),
  ('puree-saucisses', 9, 'Ajouter la muscade et saler. Servir avec les saucisses.'),
  ('quiche-lardons', 1, 'Préchauffer le four à 180 °C.'),
  ('quiche-lardons', 2, 'Étaler la pâte dans un moule à tarte en gardant son papier de cuisson.'),
  ('quiche-lardons', 3, 'Piquer le fond à la fourchette pour qu''il ne gonfle pas.'),
  ('quiche-lardons', 4, 'Dans une poêle à feu moyen, faire dorer les lardons à sec 5 minutes.'),
  ('quiche-lardons', 5, 'Les égoutter sur une assiette, puis les répartir sur la pâte.'),
  ('quiche-lardons', 6, 'Battre les œufs avec la crème, le lait, la muscade et le poivre.'),
  ('quiche-lardons', 7, 'Verser cet appareil sur les lardons.'),
  ('quiche-lardons', 8, 'Parsemer d''emmental.'),
  ('quiche-lardons', 9, 'Enfourner 35 minutes, jusqu''à ce que l''appareil soit pris et doré : il doit à peine trembler au centre.'),
  ('quiche-lardons', 10, 'Laisser reposer 5 minutes avant de couper.'),
  ('quiche-thon-tomate', 1, 'Préchauffer le four à 190 °C.'),
  ('quiche-thon-tomate', 2, 'Étaler la pâte dans un moule à tarte en gardant son papier de cuisson et piquer le fond à la fourchette.'),
  ('quiche-thon-tomate', 3, 'Badigeonner le fond de moutarde : elle protège la pâte du jus des tomates.'),
  ('quiche-thon-tomate', 4, 'Égoutter et émietter le thon, puis le répartir sur la pâte.'),
  ('quiche-thon-tomate', 5, 'Couper les tomates en rondelles et les disposer par-dessus.'),
  ('quiche-thon-tomate', 6, 'Battre les œufs avec la crème, le lait et l''emmental. Saler et poivrer.'),
  ('quiche-thon-tomate', 7, 'Verser cet appareil sur la garniture.'),
  ('quiche-thon-tomate', 8, 'Enfourner 35 minutes, jusqu''à ce que l''appareil soit pris et doré.'),
  ('quiche-thon-tomate', 9, 'Laisser reposer 5 minutes avant de couper.'),
  ('ratatouille', 1, 'Laver les légumes. Couper l''aubergine, les courgettes, les poivrons épépinés et les tomates en dés d''environ 2 cm.'),
  ('ratatouille', 2, 'Éplucher et émincer les oignons. Peler et hacher l''ail.'),
  ('ratatouille', 3, 'Chauffer un peu d''huile dans une cocotte à feu moyen-vif.'),
  ('ratatouille', 4, 'Faire dorer l''aubergine 8 minutes en remuant, puis la réserver dans un saladier.'),
  ('ratatouille', 5, 'Ajouter un peu d''huile et faire dorer les courgettes 5 minutes. Les réserver avec l''aubergine.'),
  ('ratatouille', 6, 'Ajouter un peu d''huile et faire revenir les poivrons 5 minutes. Les réserver aussi : cuits séparément, les légumes gardent leur goût.'),
  ('ratatouille', 7, 'Dans la même cocotte, faire fondre les oignons 5 minutes avec le reste d''huile, puis ajouter l''ail 1 minute.'),
  ('ratatouille', 8, 'Ajouter les tomates et cuire 5 minutes.'),
  ('ratatouille', 9, 'Remettre tous les légumes, ajouter les herbes, saler et poivrer.'),
  ('ratatouille', 10, 'Couvrir et laisser mijoter 30 minutes à feu doux en remuant délicatement de temps en temps, jusqu''à ce que les légumes soient fondants mais encore entiers.'),
  ('rigatoni-saucisse-tomate', 1, 'Éplucher et émincer l''oignon. Peler et hacher l''ail.'),
  ('rigatoni-saucisse-tomate', 2, 'Inciser le boyau des saucisses et en retirer la chair.'),
  ('rigatoni-saucisse-tomate', 3, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon 4 minutes.'),
  ('rigatoni-saucisse-tomate', 4, 'Ajouter la chair de saucisse et la faire dorer 6 minutes en l''émiettant à la cuillère en bois.'),
  ('rigatoni-saucisse-tomate', 5, 'Ajouter l''ail et remuer 1 minute.'),
  ('rigatoni-saucisse-tomate', 6, 'Verser les tomates, saler, poivrer et laisser mijoter 15 minutes à feu doux.'),
  ('rigatoni-saucisse-tomate', 7, 'Pendant ce temps, cuire les rigatoni dans une grande casserole d''eau bouillante salée 11 à 13 minutes (voir le paquet).'),
  ('rigatoni-saucisse-tomate', 8, 'Égoutter les pâtes et les mélanger à la sauce.'),
  ('rigatoni-saucisse-tomate', 9, 'Servir avec le parmesan râpé.'),
  ('risotto-butternut', 1, 'Dissoudre les cubes dans l''eau chaude et garder ce bouillon frémissant dans une casserole à feu doux.'),
  ('risotto-butternut', 2, 'Éplucher et émincer finement l''oignon. Éplucher la courge, retirer les graines et la couper en petits dés si ce n''est pas déjà fait.'),
  ('risotto-butternut', 3, 'Dans une sauteuse à fond épais, faire fondre la moitié du beurre à feu moyen et faire fondre l''oignon 3 minutes.'),
  ('risotto-butternut', 4, 'Ajouter la courge et cuire 3 minutes.'),
  ('risotto-butternut', 5, 'Ajouter le riz et le nacrer 2 minutes en remuant, jusqu''à ce que les grains deviennent translucides sur les bords.'),
  ('risotto-butternut', 6, 'Verser le vin et laisser évaporer en remuant.'),
  ('risotto-butternut', 7, 'Ajouter une louche de bouillon et remuer jusqu''à ce qu''elle soit presque absorbée.'),
  ('risotto-butternut', 8, 'Continuer louche par louche pendant 18 à 20 minutes, en remuant souvent : c''est ce qui rend le risotto crémeux.'),
  ('risotto-butternut', 9, 'Le riz doit être tendre mais encore légèrement ferme au centre.'),
  ('risotto-butternut', 10, 'Hors du feu, ajouter le reste du beurre et le parmesan, couvrir 2 minutes, puis mélanger. Saler si besoin et servir aussitôt.'),
  ('risotto-champignons', 1, 'Dissoudre le cube dans l''eau et garder ce bouillon frémissant dans une casserole à feu doux.'),
  ('risotto-champignons', 2, 'Couper le bout terreux des champignons et les émincer s''ils ne le sont pas déjà. Éplucher et hacher l''oignon.'),
  ('risotto-champignons', 3, 'Dans une sauteuse, faire dorer les champignons dans la moitié du beurre 5 minutes à feu vif, jusqu''à ce que leur eau soit évaporée. Les réserver.'),
  ('risotto-champignons', 4, 'Dans la même sauteuse, faire suer l''oignon dans l''huile 3 minutes à feu moyen.'),
  ('risotto-champignons', 5, 'Ajouter le riz et le nacrer 2 minutes en remuant.'),
  ('risotto-champignons', 6, 'Verser le vin blanc et laisser évaporer.'),
  ('risotto-champignons', 7, 'Ajouter le bouillon louche par louche en remuant souvent, en attendant que chaque louche soit presque absorbée, pendant 18 minutes.'),
  ('risotto-champignons', 8, 'Hors du feu, incorporer les champignons, le parmesan et le reste du beurre.'),
  ('risotto-champignons', 9, 'Couvrir 2 minutes, mélanger et servir : le risotto doit être crémeux et onctueux.'),
  ('risotto-petits-pois-jambon', 1, 'Dissoudre les cubes dans l''eau chaude et garder ce bouillon frémissant dans une casserole à feu doux.'),
  ('risotto-petits-pois-jambon', 2, 'Éplucher et émincer finement l''oignon. Couper le jambon en lanières.'),
  ('risotto-petits-pois-jambon', 3, 'Dans une sauteuse, faire fondre la moitié du beurre à feu moyen et faire fondre l''oignon 3 minutes.'),
  ('risotto-petits-pois-jambon', 4, 'Ajouter le riz et le nacrer 2 minutes en remuant.'),
  ('risotto-petits-pois-jambon', 5, 'Ajouter le bouillon louche par louche en remuant souvent, pendant 18 minutes.'),
  ('risotto-petits-pois-jambon', 6, 'Ajouter les petits pois avec les dernières louches, 4 à 5 minutes avant la fin.'),
  ('risotto-petits-pois-jambon', 7, 'Hors du feu, ajouter le jambon, le reste du beurre et le parmesan.'),
  ('risotto-petits-pois-jambon', 8, 'Couvrir 2 minutes, mélanger et servir aussitôt.'),
  ('riz-au-lait', 1, 'Verser le lait dans une casserole à fond épais et ajouter la vanille.'),
  ('riz-au-lait', 2, 'Porter à ébullition à feu moyen, en surveillant pour que le lait ne déborde pas.'),
  ('riz-au-lait', 3, 'Ajouter le riz en pluie et mélanger.'),
  ('riz-au-lait', 4, 'Baisser à feu très doux et cuire 40 minutes en remuant souvent, surtout vers la fin pour éviter qu''il attache.'),
  ('riz-au-lait', 5, 'Le riz est prêt quand il est fondant et que le mélange est crémeux.'),
  ('riz-au-lait', 6, 'Ajouter le sucre et remuer 2 minutes : ajouté plus tôt, il empêcherait le riz de cuire.'),
  ('riz-au-lait', 7, 'Verser dans un saladier ou des ramequins.'),
  ('riz-au-lait', 8, 'Laisser refroidir : le riz au lait épaissit en refroidissant. Servir tiède ou froid.'),
  ('riz-cantonais', 1, 'Si le riz n''est pas déjà cuit, le cuire dans une casserole d''eau bouillante 10 à 12 minutes, l''égoutter, l''étaler sur une assiette et le laisser refroidir complètement : un riz chaud colle.'),
  ('riz-cantonais', 2, 'Battre les œufs.'),
  ('riz-cantonais', 3, 'Chauffer un filet d''huile dans une poêle à feu moyen, verser les œufs et cuire une omelette fine 2 minutes.'),
  ('riz-cantonais', 4, 'La rouler et la couper en lanières.'),
  ('riz-cantonais', 5, 'Éplucher et émincer l''oignon.'),
  ('riz-cantonais', 6, 'Chauffer le reste d''huile dans un wok ou une grande poêle à feu vif et faire revenir l''oignon 2 minutes.'),
  ('riz-cantonais', 7, 'Ajouter les petits pois et le jambon en dés et faire sauter 2 minutes.'),
  ('riz-cantonais', 8, 'Ajouter le riz froid et le faire sauter 3 minutes en séparant bien les grains.'),
  ('riz-cantonais', 9, 'Ajouter la sauce soja et les lanières d''omelette et faire sauter encore 2 minutes.'),
  ('riz-haricots-rouges', 1, 'Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('riz-haricots-rouges', 2, 'Éplucher et émincer l''oignon. Épépiner le poivron et le couper en dés.'),
  ('riz-haricots-rouges', 3, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon et le poivron 5 minutes.'),
  ('riz-haricots-rouges', 4, 'Ajouter le cumin et le paprika et remuer 1 minute.'),
  ('riz-haricots-rouges', 5, 'Rincer les haricots. Les ajouter avec les tomates et saler.'),
  ('riz-haricots-rouges', 6, 'Laisser mijoter 10 minutes à feu doux.'),
  ('riz-haricots-rouges', 7, 'Mélanger avec le riz.'),
  ('riz-haricots-rouges', 8, 'Parsemer de coriandre ciselée et servir.'),
  ('riz-saute-legumes-oeuf', 1, 'Si le riz n''est pas déjà cuit, le cuire dans une casserole d''eau bouillante 10 à 12 minutes, l''égoutter, l''étaler et le laisser refroidir complètement.'),
  ('riz-saute-legumes-oeuf', 2, 'Éplucher les carottes et les couper en petits dés.'),
  ('riz-saute-legumes-oeuf', 3, 'Chauffer l''huile dans un wok ou une grande poêle à feu vif.'),
  ('riz-saute-legumes-oeuf', 4, 'Faire revenir l''oignon et les carottes 5 minutes.'),
  ('riz-saute-legumes-oeuf', 5, 'Ajouter les petits pois et le riz et faire sauter 3 minutes en séparant bien les grains.'),
  ('riz-saute-legumes-oeuf', 6, 'Pousser le riz sur le côté et casser les œufs dans l''espace libéré.'),
  ('riz-saute-legumes-oeuf', 7, 'Les brouiller 1 à 2 minutes à la spatule, puis les mélanger au riz.'),
  ('riz-saute-legumes-oeuf', 8, 'Assaisonner avec la sauce soja.'),
  ('riz-saute-legumes-oeuf', 9, 'Parsemer de ciboulette et servir.'),
  ('rougail-saucisses', 1, 'Éplucher et émincer les oignons. Peler et hacher l''ail. Peler et râper le gingembre.'),
  ('rougail-saucisses', 2, 'Couper les saucisses en tronçons et les tomates en dés.'),
  ('rougail-saucisses', 3, 'Chauffer l''huile dans une cocotte à feu moyen-vif.'),
  ('rougail-saucisses', 4, 'Faire dorer les saucisses 8 minutes en remuant. Retirer l''excédent de graisse si besoin.'),
  ('rougail-saucisses', 5, 'Ajouter les oignons, l''ail, le gingembre et le curcuma et faire revenir 5 minutes à feu moyen.'),
  ('rougail-saucisses', 6, 'Ajouter les tomates et le piment.'),
  ('rougail-saucisses', 7, 'Couvrir et laisser mijoter 30 minutes à feu doux, en remuant de temps en temps, jusqu''à ce que les tomates soient fondues en sauce.'),
  ('rougail-saucisses', 8, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('rougail-saucisses', 9, 'Servir le rougail sur le riz.'),
  ('salade-boulgour-legumes-rotis', 1, 'Préchauffer le four à 200 °C.'),
  ('salade-boulgour-legumes-rotis', 2, 'Laver l''aubergine, la courgette et le poivron. Épépiner le poivron et couper les légumes en dés d''environ 2 cm.'),
  ('salade-boulgour-legumes-rotis', 3, 'Sur la plaque du four, mélanger les légumes avec 2 cuillères d''huile et une pincée de sel, en une seule couche.'),
  ('salade-boulgour-legumes-rotis', 4, 'Rôtir 30 minutes en remuant à mi-cuisson, jusqu''à ce qu''ils soient tendres et dorés.'),
  ('salade-boulgour-legumes-rotis', 5, 'Pendant ce temps, mettre le boulgour dans une casserole avec deux fois son volume d''eau, porter à ébullition, couvrir et cuire 10 minutes à feu doux.'),
  ('salade-boulgour-legumes-rotis', 6, 'L''égrener à la fourchette et le laisser tiédir.'),
  ('salade-boulgour-legumes-rotis', 7, 'Émietter la feta et ciseler la menthe.'),
  ('salade-boulgour-legumes-rotis', 8, 'Mélanger le boulgour avec les légumes rôtis, la feta, la menthe, le jus du citron et le reste d''huile.'),
  ('salade-boulgour-legumes-rotis', 9, 'Saler si besoin et servir tiède ou froid.'),
  ('salade-cesar-poulet', 1, 'Couper le pain en cubes. Peler la gousse d''ail et l''écraser.'),
  ('salade-cesar-poulet', 2, 'Chauffer 1 cuillère d''huile dans une poêle à feu moyen avec l''ail.'),
  ('salade-cesar-poulet', 3, 'Dorer les croûtons 4 à 5 minutes en remuant, puis retirer l''ail et réserver les croûtons.'),
  ('salade-cesar-poulet', 4, 'Dans la même poêle, chauffer le reste d''huile et cuire le poulet 8 à 10 minutes en le retournant à mi-cuisson, jusqu''à ce qu''il soit cuit à cœur.'),
  ('salade-cesar-poulet', 5, 'Laisser reposer le poulet 2 minutes, puis le trancher.'),
  ('salade-cesar-poulet', 6, 'Mélanger la mayonnaise avec le jus du citron et un peu de parmesan râpé.'),
  ('salade-cesar-poulet', 7, 'Laver et essorer la salade, puis la déchirer en morceaux dans un saladier.'),
  ('salade-cesar-poulet', 8, 'Ajouter le poulet, les croûtons et la sauce et mélanger.'),
  ('salade-cesar-poulet', 9, 'Parsemer du reste de parmesan en copeaux et servir.'),
  ('salade-chevre-chaud', 1, 'Préchauffer le four à 200 °C.'),
  ('salade-chevre-chaud', 2, 'Couper le fromage de chèvre en rondelles.'),
  ('salade-chevre-chaud', 3, 'Poser les tranches de pain sur la plaque du four et poser une rondelle de chèvre sur chacune.'),
  ('salade-chevre-chaud', 4, 'Ajouter un filet de miel sur chaque toast.'),
  ('salade-chevre-chaud', 5, 'Enfourner 8 minutes, jusqu''à ce que le chèvre soit fondant et légèrement doré.'),
  ('salade-chevre-chaud', 6, 'Pendant ce temps, laver et essorer la salade.'),
  ('salade-chevre-chaud', 7, 'L''assaisonner avec l''huile et le vinaigre balsamique.'),
  ('salade-chevre-chaud', 8, 'Concasser les noix et les ajouter.'),
  ('salade-chevre-chaud', 9, 'Répartir la salade dans les assiettes et poser les toasts chauds par-dessus.'),
  ('salade-grecque', 1, 'Laver les légumes.'),
  ('salade-grecque', 2, 'Couper les tomates en quartiers et le concombre en demi-rondelles épaisses.'),
  ('salade-grecque', 3, 'Épépiner le poivron et le couper en lanières. Éplucher l''oignon rouge et l''émincer finement.'),
  ('salade-grecque', 4, 'Réunir les légumes dans un saladier et ajouter les olives.'),
  ('salade-grecque', 5, 'Couper la feta en dés, ou la poser en une tranche sur le dessus.'),
  ('salade-grecque', 6, 'Arroser d''huile d''olive et parsemer d''herbes de Provence.'),
  ('salade-grecque', 7, 'Servir avec le pain.'),
  ('salade-lentilles-feta', 1, 'Rincer les lentilles.'),
  ('salade-lentilles-feta', 2, 'Les mettre dans une casserole d''eau froide sans sel et porter à frémissement : le sel durcit leur peau.'),
  ('salade-lentilles-feta', 3, 'Cuire 20 minutes : elles doivent être tendres mais encore entières. Les égoutter.'),
  ('salade-lentilles-feta', 4, 'Dans un saladier, fouetter la moutarde avec le vinaigre, puis ajouter l''huile en fouettant.'),
  ('salade-lentilles-feta', 5, 'Couper les tomates cerises en deux et le concombre en dés.'),
  ('salade-lentilles-feta', 6, 'Ajouter les légumes, l''oignon et les lentilles encore tièdes : elles absorbent mieux la vinaigrette.'),
  ('salade-lentilles-feta', 7, 'Ajouter la feta et le persil ciselé.'),
  ('salade-lentilles-feta', 8, 'Mélanger délicatement et servir tiède ou froid.'),
  ('salade-nicoise', 1, 'Plonger les œufs dans une casserole d''eau bouillante et les cuire 10 minutes.'),
  ('salade-nicoise', 2, 'Les refroidir dans l''eau froide, puis les écaler.'),
  ('salade-nicoise', 3, 'Équeuter les haricots verts et les cuire 6 minutes dans une casserole d''eau bouillante salée.'),
  ('salade-nicoise', 4, 'Les refroidir aussitôt à l''eau froide pour qu''ils restent bien verts, puis les égoutter.'),
  ('salade-nicoise', 5, 'Préparer la vinaigrette en fouettant le vinaigre, une pincée de sel et l''huile.'),
  ('salade-nicoise', 6, 'Laver et essorer la salade. Couper les tomates et les œufs en quartiers. Éplucher et émincer l''oignon rouge.'),
  ('salade-nicoise', 7, 'Égoutter le thon.'),
  ('salade-nicoise', 8, 'Disposer la salade dans un grand saladier ou sur les assiettes, puis les tomates, le thon, les œufs, les haricots, les olives et l''oignon.'),
  ('salade-nicoise', 9, 'Arroser de vinaigrette juste avant de servir.'),
  ('salade-pates-thon', 1, 'Cuire les pâtes dans une grande casserole d''eau bouillante 9 à 11 minutes (voir le paquet).'),
  ('salade-pates-thon', 2, 'Les égoutter, les passer sous l''eau froide pour stopper la cuisson et bien les égoutter.'),
  ('salade-pates-thon', 3, 'Si vous ajoutez des œufs, les cuire 10 minutes dans l''eau bouillante, les refroidir et les écaler.'),
  ('salade-pates-thon', 4, 'Égoutter le thon et l''émietter. Couper les tomates cerises en deux. Égoutter le maïs.'),
  ('salade-pates-thon', 5, 'Fouetter le vinaigre et l''huile, avec la mayonnaise si vous l''utilisez.'),
  ('salade-pates-thon', 6, 'Mélanger les pâtes, le thon, les tomates et le maïs avec la sauce.'),
  ('salade-pates-thon', 7, 'Ajouter les œufs durs en quartiers au moment de servir.'),
  ('salade-piemontaise', 1, 'Mettre les pommes de terre non épluchées dans une casserole d''eau froide salée.'),
  ('salade-piemontaise', 2, 'Porter à ébullition et cuire 20 minutes, jusqu''à ce qu''elles soient tendres. Les égoutter et les laisser refroidir.'),
  ('salade-piemontaise', 3, 'Cuire les œufs 10 minutes dans une casserole d''eau bouillante, les refroidir à l''eau froide et les écaler.'),
  ('salade-piemontaise', 4, 'Éplucher les pommes de terre et les couper en dés.'),
  ('salade-piemontaise', 5, 'Couper les œufs, le jambon, les tomates et les cornichons en dés.'),
  ('salade-piemontaise', 6, 'Mélanger la mayonnaise et la moutarde dans un saladier.'),
  ('salade-piemontaise', 7, 'Ajouter tous les ingrédients et mélanger délicatement.'),
  ('salade-piemontaise', 8, 'Parsemer de persil ciselé et réfrigérer jusqu''au service.'),
  ('salade-quinoa-avocat-mais', 1, 'Rincer le quinoa dans une passoire fine.'),
  ('salade-quinoa-avocat-mais', 2, 'Le cuire 12 minutes dans une casserole d''eau bouillante, puis l''égoutter et le rincer à l''eau froide.'),
  ('salade-quinoa-avocat-mais', 3, 'Rincer et égoutter le maïs et les haricots.'),
  ('salade-quinoa-avocat-mais', 4, 'Couper les tomates cerises en deux.'),
  ('salade-quinoa-avocat-mais', 5, 'Couper les avocats en deux, retirer le noyau et couper la chair en dés.'),
  ('salade-quinoa-avocat-mais', 6, 'Dans un saladier, mélanger le quinoa avec le maïs, les haricots, les tomates et l''avocat.'),
  ('salade-quinoa-avocat-mais', 7, 'Assaisonner avec le jus des citrons verts, l''huile, la coriandre ciselée et le sel.'),
  ('salade-quinoa-avocat-mais', 8, 'Servir frais.'),
  ('salade-riz-thon', 1, 'Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes.'),
  ('salade-riz-thon', 2, 'L''égoutter, le rincer à l''eau froide et le laisser refroidir.'),
  ('salade-riz-thon', 3, 'Cuire les œufs 10 minutes dans une casserole d''eau bouillante, les refroidir à l''eau froide et les écaler.'),
  ('salade-riz-thon', 4, 'Laver les tomates et le poivron. Épépiner le poivron. Couper les tomates, le poivron et les œufs en dés.'),
  ('salade-riz-thon', 5, 'Égoutter et émietter le thon. Égoutter le maïs.'),
  ('salade-riz-thon', 6, 'Dans un saladier, fouetter la moutarde et le vinaigre avec une pincée de sel, puis ajouter l''huile en fouettant.'),
  ('salade-riz-thon', 7, 'Ajouter le riz, le thon, le maïs, les légumes, les œufs et les olives.'),
  ('salade-riz-thon', 8, 'Mélanger et réfrigérer jusqu''au service.'),
  ('saumon-grenailles-citron', 1, 'Préchauffer le four à 200 °C.'),
  ('saumon-grenailles-citron', 2, 'Laver les grenailles sans les éplucher et les couper en deux.'),
  ('saumon-grenailles-citron', 3, 'Dans un plat allant au four, les mélanger avec l''huile, du sel et du poivre, et les poser face coupée vers le bas : elles doreront mieux.'),
  ('saumon-grenailles-citron', 4, 'Rôtir 25 minutes, jusqu''à ce qu''elles soient dorées.'),
  ('saumon-grenailles-citron', 5, 'Pendant ce temps, couper le citron en deux et presser une moitié.'),
  ('saumon-grenailles-citron', 6, 'Poser les pavés de saumon parmi les pommes de terre. Les arroser du jus de citron, puis les saler et les poivrer.'),
  ('saumon-grenailles-citron', 7, 'Remettre au four 12 minutes : le saumon doit être rosé au centre et s''effeuiller facilement.'),
  ('saumon-grenailles-citron', 8, 'Parsemer de ciboulette ciselée et servir avec le reste du citron en quartiers.'),
  ('saumon-riz-brocoli', 1, 'Préchauffer le four à 200 °C.'),
  ('saumon-riz-brocoli', 2, 'Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('saumon-riz-brocoli', 3, 'Couper le citron en deux et presser une moitié.'),
  ('saumon-riz-brocoli', 4, 'Disposer les pavés de saumon dans un plat allant au four.'),
  ('saumon-riz-brocoli', 5, 'Les arroser d''huile et de jus de citron.'),
  ('saumon-riz-brocoli', 6, 'Enfourner 15 minutes : la chair doit être rosée au centre et s''effeuiller facilement.'),
  ('saumon-riz-brocoli', 7, 'Pendant ce temps, cuire le brocoli 6 minutes à la vapeur : il doit rester vert vif et légèrement croquant.'),
  ('saumon-riz-brocoli', 8, 'Servir le saumon avec le riz, le brocoli et le reste du citron en quartiers.'),
  ('shakshuka', 1, 'Éplucher et émincer l''oignon. Peler et hacher l''ail. Épépiner les poivrons et les couper en lanières.'),
  ('shakshuka', 2, 'Chauffer l''huile dans une grande poêle à feu moyen.'),
  ('shakshuka', 3, 'Faire revenir l''oignon, les poivrons et l''ail 8 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('shakshuka', 4, 'Ajouter le cumin et le paprika et remuer 1 minute.'),
  ('shakshuka', 5, 'Verser les tomates, saler et laisser réduire 10 minutes à feu moyen-doux, jusqu''à ce que la sauce épaississe.'),
  ('shakshuka', 6, 'Creuser des puits dans la sauce avec le dos d''une cuillère.'),
  ('shakshuka', 7, 'Casser un œuf dans chaque puits, en veillant à ne pas crever les jaunes.'),
  ('shakshuka', 8, 'Couvrir et cuire 6 à 8 minutes à feu doux, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.'),
  ('shakshuka', 9, 'Parsemer de coriandre ciselée et servir directement dans la poêle, avec le pain.'),
  ('soupe-legumes-hiver', 1, 'Éplucher et émincer l''oignon. Émincer le poireau et bien le rincer.'),
  ('soupe-legumes-hiver', 2, 'Éplucher les pommes de terre, les carottes et le navet et les couper en dés.'),
  ('soupe-legumes-hiver', 3, 'Dans un faitout à feu moyen, faire suer l''oignon et le poireau 5 minutes avec un petit filet d''eau, à couvert, sans coloration.'),
  ('soupe-legumes-hiver', 4, 'Ajouter les autres légumes, le cube émietté et l''eau.'),
  ('soupe-legumes-hiver', 5, 'Porter à ébullition, puis cuire 30 minutes à frémissement, jusqu''à ce que les légumes s''écrasent facilement à la fourchette.'),
  ('soupe-legumes-hiver', 6, 'Mixer jusqu''à obtenir une soupe lisse.'),
  ('soupe-legumes-hiver', 7, 'Ajouter la crème, saler et poivrer.'),
  ('soupe-legumes-hiver', 8, 'Servir bien chaud.'),
  ('soupe-lentilles-corail-carottes', 1, 'Rincer les lentilles dans une passoire jusqu''à ce que l''eau soit claire.'),
  ('soupe-lentilles-corail-carottes', 2, 'Éplucher et émincer l''oignon. Éplucher les carottes et les couper en rondelles fines.'),
  ('soupe-lentilles-corail-carottes', 3, 'Chauffer l''huile dans un faitout à feu moyen.'),
  ('soupe-lentilles-corail-carottes', 4, 'Faire revenir l''oignon avec le cumin 3 minutes.'),
  ('soupe-lentilles-corail-carottes', 5, 'Ajouter les carottes, les lentilles, l''eau et le cube émietté.'),
  ('soupe-lentilles-corail-carottes', 6, 'Porter à ébullition, puis cuire 20 minutes à frémissement, jusqu''à ce que les carottes soient tendres et les lentilles défaites.'),
  ('soupe-lentilles-corail-carottes', 7, 'Ajouter le lait de coco.'),
  ('soupe-lentilles-corail-carottes', 8, 'Mixer jusqu''à obtenir une soupe lisse. Saler et servir chaud.'),
  ('soupe-miso-legumes', 1, 'Couper le bout terreux des champignons et les émincer finement.'),
  ('soupe-miso-legumes', 2, 'Éplucher la carotte et la couper en fines rondelles. Peler et râper le gingembre.'),
  ('soupe-miso-legumes', 3, 'Couper le tofu en cubes.'),
  ('soupe-miso-legumes', 4, 'Dans une casserole, porter l''eau à ébullition avec le cube émietté, le gingembre et la sauce soja.'),
  ('soupe-miso-legumes', 5, 'Ajouter les champignons et la carotte et cuire 5 minutes à frémissement.'),
  ('soupe-miso-legumes', 6, 'Ajouter les nouilles et le tofu et cuire 4 minutes, jusqu''à ce que les nouilles soient souples.'),
  ('soupe-miso-legumes', 7, 'Hors du feu, ajouter les épinards : ils tombent en 1 minute dans le bouillon chaud.'),
  ('soupe-miso-legumes', 8, 'Servir aussitôt dans des bols.'),
  ('soupe-oignon-gratinee', 1, 'Éplucher les oignons et les émincer finement s''ils ne le sont pas déjà.'),
  ('soupe-oignon-gratinee', 2, 'Dans un faitout, faire fondre le beurre à feu doux et ajouter les oignons.'),
  ('soupe-oignon-gratinee', 3, 'Les cuire 25 minutes en remuant régulièrement, jusqu''à ce qu''ils soient fondants et bien dorés : c''est cette caramélisation lente qui fait tout le goût.'),
  ('soupe-oignon-gratinee', 4, 'Saupoudrer de farine et remuer 1 minute.'),
  ('soupe-oignon-gratinee', 5, 'Verser le vin et laisser bouillir 1 minute, puis ajouter l''eau et les cubes émiettés.'),
  ('soupe-oignon-gratinee', 6, 'Cuire 20 minutes à frémissement. Poivrer.'),
  ('soupe-oignon-gratinee', 7, 'Allumer le gril du four. Faire griller les tranches de pain.'),
  ('soupe-oignon-gratinee', 8, 'Répartir la soupe dans des bols allant au four.'),
  ('soupe-oignon-gratinee', 9, 'Couvrir de pain grillé, puis d''emmental.'),
  ('soupe-oignon-gratinee', 10, 'Passer 5 minutes sous le gril du four, jusqu''à ce que le fromage soit doré et bouillonnant. Servir aussitôt.'),
  ('soupe-potiron', 1, 'Éplucher et émincer l''oignon.'),
  ('soupe-potiron', 2, 'Éplucher le potiron, retirer les graines et le couper en cubes. Éplucher la pomme de terre et la couper en cubes.'),
  ('soupe-potiron', 3, 'Dans un faitout à feu moyen, faire suer l''oignon 3 minutes avec un petit filet d''eau, sans coloration.'),
  ('soupe-potiron', 4, 'Ajouter le potiron, la pomme de terre, le cube émietté et l''eau.'),
  ('soupe-potiron', 5, 'Porter à ébullition, puis cuire 25 minutes à frémissement, jusqu''à ce que les légumes s''écrasent à la fourchette.'),
  ('soupe-potiron', 6, 'Mixer finement jusqu''à obtenir un velouté lisse.'),
  ('soupe-potiron', 7, 'Ajouter la crème et la muscade, puis saler.'),
  ('soupe-potiron', 8, 'Servir chaud.'),
  ('soupe-thai-poulet-coco', 1, 'Couper le bout terreux des champignons et les émincer finement.'),
  ('soupe-thai-poulet-coco', 2, 'Couper le poulet en fines lanières si ce n''est pas déjà fait.'),
  ('soupe-thai-poulet-coco', 3, 'Dans une casserole à feu moyen, faire chauffer la pâte de curry 1 minute en remuant, jusqu''à ce qu''elle embaume.'),
  ('soupe-thai-poulet-coco', 4, 'Ajouter le lait de coco, l''eau et le cube émietté, puis porter à frémissement.'),
  ('soupe-thai-poulet-coco', 5, 'Ajouter le poulet et les champignons.'),
  ('soupe-thai-poulet-coco', 6, 'Cuire 10 minutes à frémissement, jusqu''à ce que le poulet soit cuit à cœur.'),
  ('soupe-thai-poulet-coco', 7, 'Ajouter les nouilles de riz et cuire 4 minutes, jusqu''à ce qu''elles soient souples.'),
  ('soupe-thai-poulet-coco', 8, 'Hors du feu, ajouter le jus du citron vert et la coriandre ciselée.'),
  ('soupe-thai-poulet-coco', 9, 'Servir aussitôt dans des bols.'),
  ('soupe-tomate-pois-chiches', 1, 'Éplucher et émincer l''oignon et l''ail. Éplucher les carottes et les couper en petits dés.'),
  ('soupe-tomate-pois-chiches', 2, 'Chauffer l''huile dans un faitout à feu moyen.'),
  ('soupe-tomate-pois-chiches', 3, 'Faire revenir l''oignon, les carottes et l''ail 5 minutes.'),
  ('soupe-tomate-pois-chiches', 4, 'Ajouter le cumin et le paprika et remuer 1 minute.'),
  ('soupe-tomate-pois-chiches', 5, 'Ajouter les tomates, le cube émietté et l''eau.'),
  ('soupe-tomate-pois-chiches', 6, 'Cuire 20 minutes à frémissement, jusqu''à ce que les carottes soient tendres.'),
  ('soupe-tomate-pois-chiches', 7, 'Mixer à moitié, pour garder des morceaux.'),
  ('soupe-tomate-pois-chiches', 8, 'Rincer les pois chiches, les ajouter et réchauffer 5 minutes à feu doux avant de servir.'),
  ('spaghetti-aglio-olio', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les spaghetti 9 à 11 minutes (voir le paquet).'),
  ('spaghetti-aglio-olio', 2, 'Pendant ce temps, ciseler le persil.'),
  ('spaghetti-aglio-olio', 3, 'Mettre l''huile, l''ail en lamelles et le piment dans une grande poêle froide.'),
  ('spaghetti-aglio-olio', 4, 'Chauffer à feu doux 3 à 4 minutes, jusqu''à ce que l''ail blondisse à peine : s''il brunit, il devient amer.'),
  ('spaghetti-aglio-olio', 5, 'Prélever une petite louche d''eau de cuisson, puis égoutter les pâtes.'),
  ('spaghetti-aglio-olio', 6, 'Verser les pâtes dans la poêle avec l''eau de cuisson.'),
  ('spaghetti-aglio-olio', 7, 'Mélanger 1 minute à feu moyen, jusqu''à ce que la sauce enrobe les spaghetti.'),
  ('spaghetti-aglio-olio', 8, 'Ajouter le persil et servir avec le parmesan.'),
  ('spaghetti-carbonara', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les spaghetti 9 à 11 minutes (voir le paquet).'),
  ('spaghetti-carbonara', 2, 'Pendant ce temps, faire dorer les lardons à sec 5 minutes dans une grande poêle à feu moyen, jusqu''à ce qu''ils soient croustillants. Retirer du feu.'),
  ('spaghetti-carbonara', 3, 'Dans un bol, battre l''œuf entier et les jaunes avec le parmesan et beaucoup de poivre.'),
  ('spaghetti-carbonara', 4, 'Prélever une louche d''eau de cuisson.'),
  ('spaghetti-carbonara', 5, 'Égoutter les pâtes et les verser dans la poêle avec les lardons, hors du feu. Mélanger.'),
  ('spaghetti-carbonara', 6, 'Ajouter le mélange aux œufs et un peu d''eau de cuisson.'),
  ('spaghetti-carbonara', 7, 'Remuer vivement pendant 1 minute : la chaleur des pâtes épaissit la sauce sans cuire les œufs en omelette.'),
  ('spaghetti-carbonara', 8, 'Servir aussitôt, avec un tour de poivre.'),
  ('steak-hache-frites-four', 1, 'Préchauffer le four à 220 °C.'),
  ('steak-hache-frites-four', 2, 'Éplucher les pommes de terre et les couper en frites d''environ 1 cm.'),
  ('steak-hache-frites-four', 3, 'Les rincer à l''eau froide pour retirer l''amidon, puis bien les sécher dans un torchon : c''est ce qui les rend croustillantes.'),
  ('steak-hache-frites-four', 4, 'Mélanger les frites avec l''huile et le sel.'),
  ('steak-hache-frites-four', 5, 'Les étaler en une seule couche sur la plaque du four, sans qu''elles se chevauchent.'),
  ('steak-hache-frites-four', 6, 'Enfourner 35 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et croustillantes.'),
  ('steak-hache-frites-four', 7, 'Dix minutes avant la fin, chauffer une poêle à feu vif.'),
  ('steak-hache-frites-four', 8, 'Cuire les steaks 2 à 4 minutes par face selon la cuisson souhaitée. Saler.'),
  ('steak-hache-frites-four', 9, 'Servir avec la salade et le ketchup.'),
  ('steak-haricots-verts', 1, 'Sortir les steaks du réfrigérateur 10 minutes avant.'),
  ('steak-haricots-verts', 2, 'Éplucher les pommes de terre et les couper en dés d''environ 1,5 cm.'),
  ('steak-haricots-verts', 3, 'Chauffer l''huile dans une poêle à feu moyen-vif et faire sauter les pommes de terre 20 minutes en remuant régulièrement, jusqu''à ce qu''elles soient dorées et tendres.'),
  ('steak-haricots-verts', 4, 'Pendant ce temps, équeuter les haricots verts.'),
  ('steak-haricots-verts', 5, 'Les cuire 8 minutes dans une casserole d''eau bouillante, puis les égoutter.'),
  ('steak-haricots-verts', 6, 'Peler et hacher l''ail. Ciseler le persil.'),
  ('steak-haricots-verts', 7, 'Faire fondre la moitié du beurre dans une autre poêle à feu vif.'),
  ('steak-haricots-verts', 8, 'Saisir les steaks 2 à 3 minutes par face selon la cuisson souhaitée, puis les laisser reposer 2 minutes.'),
  ('steak-haricots-verts', 9, 'Dans la poêle des steaks, faire fondre le reste du beurre et faire sauter les haricots 2 minutes avec l''ail et le persil.'),
  ('steak-haricots-verts', 10, 'Servir avec les pommes de terre.'),
  ('taboule', 1, 'Dans un saladier, mélanger la semoule avec le jus des citrons, l''huile et 20 cl d''eau froide.'),
  ('taboule', 2, 'Laisser gonfler 15 minutes, puis l''égrener à la fourchette.'),
  ('taboule', 3, 'Pendant ce temps, laver les tomates et le concombre et les couper en petits dés.'),
  ('taboule', 4, 'Éplucher l''oignon rouge et le couper en petits dés.'),
  ('taboule', 5, 'Laver le persil et la menthe, les sécher et les hacher finement.'),
  ('taboule', 6, 'Mélanger les légumes et les herbes avec la semoule. Saler.'),
  ('taboule', 7, 'Réfrigérer au moins 30 minutes : la semoule finit d''absorber le jus des légumes.'),
  ('taboule', 8, 'Égrener de nouveau avant de servir.'),
  ('tacos-poulet', 1, 'Mélanger le poulet avec le paprika, le cumin et la moitié de l''huile.'),
  ('tacos-poulet', 2, 'Épépiner le poivron et le couper en lanières s''il ne l''est pas déjà.'),
  ('tacos-poulet', 3, 'Chauffer le reste d''huile dans une poêle à feu vif.'),
  ('tacos-poulet', 4, 'Saisir le poulet et le poivron 8 à 10 minutes en remuant, jusqu''à ce que le poulet soit doré et cuit à cœur.'),
  ('tacos-poulet', 5, 'Mélanger le fromage blanc avec le jus du citron vert.'),
  ('tacos-poulet', 6, 'Laver et essorer la salade. Couper les tomates en dés.'),
  ('tacos-poulet', 7, 'Réchauffer les tortillas 20 secondes de chaque côté dans une poêle sèche.'),
  ('tacos-poulet', 8, 'Les garnir de salade, de tomate, de poulet et de sauce.'),
  ('tacos-poulet', 9, 'Les rouler et servir aussitôt.'),
  ('tagliatelles-champignons-creme', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les tagliatelles 6 à 8 minutes (voir le paquet).'),
  ('tagliatelles-champignons-creme', 2, 'Pendant ce temps, couper le bout terreux des champignons et les émincer s''ils ne le sont pas déjà. Hacher l''échalote et l''ail.'),
  ('tagliatelles-champignons-creme', 3, 'Faire fondre le beurre dans une grande poêle à feu moyen et faire revenir l''échalote 2 minutes.'),
  ('tagliatelles-champignons-creme', 4, 'Monter à feu vif, ajouter les champignons et les faire dorer 6 à 8 minutes, jusqu''à ce que leur eau soit évaporée.'),
  ('tagliatelles-champignons-creme', 5, 'Ajouter l''ail et remuer 1 minute.'),
  ('tagliatelles-champignons-creme', 6, 'Verser la crème et laisser réduire 3 minutes. Saler et poivrer.'),
  ('tagliatelles-champignons-creme', 7, 'Égoutter les tagliatelles en gardant un peu d''eau de cuisson.'),
  ('tagliatelles-champignons-creme', 8, 'Les mélanger à la sauce, en la détendant avec un peu d''eau de cuisson si besoin.'),
  ('tagliatelles-champignons-creme', 9, 'Servir avec le persil ciselé et le parmesan.'),
  ('tarte-fine-tomate-mozzarella', 1, 'Préchauffer le four à 200 °C.'),
  ('tarte-fine-tomate-mozzarella', 2, 'Dérouler la pâte sur la plaque du four avec son papier et la piquer à la fourchette.'),
  ('tarte-fine-tomate-mozzarella', 3, 'La tartiner de pesto en laissant un bord libre de 2 cm.'),
  ('tarte-fine-tomate-mozzarella', 4, 'Couper les tomates et la mozzarella en tranches et les laisser égoutter quelques minutes sur une assiette : la pâte restera croustillante.'),
  ('tarte-fine-tomate-mozzarella', 5, 'Disposer les tomates et la mozzarella en les alternant.'),
  ('tarte-fine-tomate-mozzarella', 6, 'Saler légèrement et arroser d''huile.'),
  ('tarte-fine-tomate-mozzarella', 7, 'Enfourner 25 minutes, jusqu''à ce que la pâte soit bien dorée et gonflée sur les bords.'),
  ('tarte-fine-tomate-mozzarella', 8, 'Parsemer de basilic au moment de servir.'),
  ('tarte-poireaux-chevre', 1, 'Préchauffer le four à 180 °C.'),
  ('tarte-poireaux-chevre', 2, 'Couper la base et le haut vert foncé des poireaux, les émincer et bien les rincer.'),
  ('tarte-poireaux-chevre', 3, 'Faire fondre le beurre dans une poêle à feu doux.'),
  ('tarte-poireaux-chevre', 4, 'Ajouter les poireaux et les faire fondre 15 minutes à couvert, en remuant de temps en temps, sans coloration.'),
  ('tarte-poireaux-chevre', 5, 'Étaler la pâte dans un moule à tarte en gardant son papier de cuisson et piquer le fond.'),
  ('tarte-poireaux-chevre', 6, 'Répartir les poireaux sur la pâte.'),
  ('tarte-poireaux-chevre', 7, 'Battre les œufs avec la crème et poivrer, puis verser sur les poireaux.'),
  ('tarte-poireaux-chevre', 8, 'Couper le chèvre en rondelles et les disposer sur le dessus.'),
  ('tarte-poireaux-chevre', 9, 'Enfourner 35 minutes, jusqu''à ce que l''appareil soit pris et doré.'),
  ('tarte-poireaux-chevre', 10, 'Laisser reposer 5 minutes avant de couper.'),
  ('tofu-croustillant-brocoli', 1, 'Lancer le riz dans une casserole d''eau bouillante, 10 à 12 minutes, puis l''égoutter.'),
  ('tofu-croustillant-brocoli', 2, 'Peler et hacher l''ail. Peler et râper le gingembre. Détailler le brocoli en petits bouquets.'),
  ('tofu-croustillant-brocoli', 3, 'Éponger le tofu avec un torchon : moins il est humide, plus il sera croustillant.'),
  ('tofu-croustillant-brocoli', 4, 'Rouler les cubes de tofu dans la fécule.'),
  ('tofu-croustillant-brocoli', 5, 'Chauffer l''huile de tournesol dans une grande poêle à feu moyen-vif.'),
  ('tofu-croustillant-brocoli', 6, 'Dorer le tofu 10 minutes en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces.'),
  ('tofu-croustillant-brocoli', 7, 'Ajouter le brocoli, l''ail et le gingembre et faire sauter 5 minutes, jusqu''à ce que le brocoli soit tendre mais encore croquant.'),
  ('tofu-croustillant-brocoli', 8, 'Ajouter la sauce soja et l''huile de sésame et mélanger 30 secondes.'),
  ('tofu-croustillant-brocoli', 9, 'Parsemer de graines de sésame et servir avec le riz.'),
  ('tortilla-espagnole', 1, 'Éplucher les pommes de terre et les couper en fines tranches. Éplucher et émincer l''oignon.'),
  ('tortilla-espagnole', 2, 'Chauffer l''huile dans une poêle à feu doux.'),
  ('tortilla-espagnole', 3, 'Ajouter les pommes de terre et l''oignon et les cuire 20 minutes en remuant de temps en temps : ils doivent être tendres mais pas dorés.'),
  ('tortilla-espagnole', 4, 'Battre les œufs avec le sel dans un saladier.'),
  ('tortilla-espagnole', 5, 'Égoutter les pommes de terre et l''oignon en gardant un peu d''huile, puis les mélanger aux œufs.'),
  ('tortilla-espagnole', 6, 'Remettre un filet de cette huile dans la poêle à feu doux et verser le mélange.'),
  ('tortilla-espagnole', 7, 'Cuire 8 minutes, jusqu''à ce que les bords soient pris.'),
  ('tortilla-espagnole', 8, 'Poser une grande assiette sur la poêle, retourner la tortilla dessus d''un geste franc, puis la faire glisser à nouveau dans la poêle.'),
  ('tortilla-espagnole', 9, 'Cuire encore 5 minutes.'),
